// Normalization and deduplication of findings from all four scanning layers.
//
// Every finding, whichever layer produced it, becomes one record in the common schema:
//   {
//     wcagCriterion: '1.1.1',
//     level: 'A',
//     engineSource: ['axe-core', 'IBM Equal Access'],   // every layer that detected it
//     element: '#logo',                                 // unique element key within the page
//     snippet: '<img id="logo" src="...">',
//     description: 'Images must have alternative text',
//     rules: [{ engine, ruleId, description }, ...],    // one entry per engine rule
//   }
//
// Deduplication rule: records for the SAME element and the SAME criterion collapse into
// one, with engineSource and rules unioned. Records for the same criterion on DIFFERENT
// elements are separate findings and are never merged. Element identity only makes sense
// within one page, so deduplication is always per page.

const { WCAG22_ALL } = require('./wcag');

const ENGINES = {
  AXE: 'axe-core',
  IBM: 'IBM Equal Access',
  HTMLCS: 'HTML CodeSniffer',
  KEYBOARD: 'Keyboard simulation',
};
// Display order, and which engine's wording describes a finding several engines share.
const ENGINE_ORDER = [ENGINES.AXE, ENGINES.IBM, ENGINES.HTMLCS, ENGINES.KEYBOARD];
const RULE_ENGINES = [ENGINES.AXE, ENGINES.IBM, ENGINES.HTMLCS];

const LEVEL_BY_SC = {};
for (const c of WCAG22_ALL) LEVEL_BY_SC[c.sc] = c.level;

const byEngineOrder = (a, b) => ENGINE_ORDER.indexOf(a) - ENGINE_ORDER.indexOf(b);

function dedupe(records) {
  const merged = new Map();
  for (const r of records) {
    const id = `${r.wcagCriterion}\u0000${r.element}`;
    let m = merged.get(id);
    if (!m) {
      m = { ...r, engineSource: [], rules: [] };
      merged.set(id, m);
    }
    for (const engine of r.engineSource) if (!m.engineSource.includes(engine)) m.engineSource.push(engine);
    for (const rule of r.rules) {
      if (!m.rules.some((x) => x.engine === rule.engine && x.ruleId === rule.ruleId)) m.rules.push(rule);
    }
    if (!m.snippet && r.snippet) m.snippet = r.snippet;
  }
  const out = [...merged.values()];
  for (const m of out) {
    m.engineSource.sort(byEngineOrder);
    m.rules.sort((a, b) => byEngineOrder(a.engine, b.engine));
    m.description = m.rules.length ? m.rules[0].description : m.description;
  }
  return out;
}

function groupByCriterion(records) {
  const groups = {};
  for (const r of records) (groups[r.wcagCriterion] = groups[r.wcagCriterion] || []).push(r);
  return groups;
}

// Page property that holds each rule engine's results.
const RESULT_KEY = {
  [ENGINES.AXE]: 'axeResults',
  [ENGINES.IBM]: 'ibmResults',
  [ENGINES.HTMLCS]: 'codesnifferResults',
};

const hasEngineScan = (page) => !!page.engines;
const hasKeyboardScan = (page) => !!(page.keyboardResults && page.keyboardResults.ranAt);

// Turns the raw result of engineScanInPage into what is stored on the page. Each engine's
// violations are kept in their own array as [criterion, elementIndex, ruleIndex] rows
// that index into shared tables, because a session lives in localStorage.
//   engines.elements: [[key, snippet]]   engines.rules: [[engine, ruleId, description]]
//   engines.review:   { criterion: count of elements needing manual review }
function packEngineScan(raw) {
  const kept = new Map();
  const violating = new Set();
  const review = new Map();
  for (const [sc, el, rule, kind] of raw.records) {
    if (!LEVEL_BY_SC[sc]) continue; // AAA or non-WCAG policy rules are outside this report
    if (kind === 'v') {
      kept.set(`${sc}\u0000${el}\u0000${rule}`, [sc, el, rule]);
      violating.add(`${sc}\u0000${el}`);
    } else review.set(`${sc}\u0000${el}`, sc);
  }
  const reviewCounts = {};
  for (const [id, sc] of review) {
    if (!violating.has(id)) reviewCounts[sc] = (reviewCounts[sc] || 0) + 1;
  }

  // Re-index so the tables hold only rows a violation points at.
  const elementMap = new Map();
  const ruleMap = new Map();
  const elements = [];
  const rules = [];
  const out = { axeResults: [], ibmResults: [], codesnifferResults: [] };
  for (const [sc, el, rule] of kept.values()) {
    if (!elementMap.has(el)) {
      elementMap.set(el, elements.length);
      elements.push(raw.elements[el]);
    }
    if (!ruleMap.has(rule)) {
      ruleMap.set(rule, rules.length);
      rules.push(raw.rules[rule]);
    }
    const key = RESULT_KEY[raw.rules[rule][0]];
    if (key) out[key].push([sc, elementMap.get(el), ruleMap.get(rule)]);
  }

  const coveredSc = {};
  for (const engine of Object.keys(raw.covered || {})) {
    coveredSc[engine] = raw.covered[engine].filter((sc) => LEVEL_BY_SC[sc]).sort();
  }
  return {
    url: raw.url,
    ...out,
    engines: { versions: raw.versions, errors: raw.errors, coveredSc, review: reviewCounts, elements, rules },
  };
}

// One common-schema record per engine result; dedupe() merges them across engines.
function engineRecords(page) {
  const { elements, rules } = page.engines;
  const out = [];
  for (const engine of RULE_ENGINES) {
    for (const [sc, el, r] of page[RESULT_KEY[engine]] || []) {
      const description = rules[r][2];
      out.push({
        wcagCriterion: sc,
        level: LEVEL_BY_SC[sc],
        engineSource: [engine],
        element: elements[el][0],
        snippet: elements[el][1],
        description,
        rules: [{ engine, ruleId: rules[r][1], description }],
      });
    }
  }
  return out;
}

// Success criteria the keyboard scan reports on.
const KEYBOARD_CRITERIA = ['2.1.1', '2.1.2', '2.4.1', '2.4.7', '2.4.11'];

function keyboardRecords(kb) {
  const out = [];
  const add = (sc, element, snippet, description) => {
    out.push({
      wcagCriterion: sc,
      level: LEVEL_BY_SC[sc],
      engineSource: [ENGINES.KEYBOARD],
      element,
      snippet,
      description,
      rules: [{ engine: ENGINES.KEYBOARD, ruleId: sc, description }],
    });
  };
  const label = (x) => `${x.el}${x.label ? ` "${x.label}"` : ''}`;
  (kb.unreachable || []).forEach((u, i) => add('2.1.1', u.key || `unreachable:${i}`, label(u), `Not reachable with the Tab key: ${u.reason}`));
  (kb.traps || []).forEach((t, i) => add('2.1.2', t.key || `trap:${i}`, label(t), `Keyboard trap: ${t.detail}`));
  if (!(kb.skipLink && kb.skipLink.present)) add('2.4.1', 'html', '(whole page)', 'No skip link found');
  for (const s of kb.stops || []) {
    const key = s.key || `stop:${s.i}`;
    if (s.ind === 'missing') add('2.4.7', key, label(s), 'No visible focus indicator');
    if (s.obscured) add('2.4.11', key, label(s), `Entirely hidden behind ${s.obscured} when focused`);
  }
  return out;
}

// All findings for one page, from every layer that has run on it, deduplicated.
const cache = new WeakMap();
function pageFindings(page) {
  const hit = cache.get(page);
  if (hit && hit.engines === page.engines && hit.keyboard === page.keyboardResults) return hit.records;
  const records = dedupe([
    ...(hasEngineScan(page) ? engineRecords(page) : []),
    ...(hasKeyboardScan(page) ? keyboardRecords(page.keyboardResults) : []),
  ]);
  cache.set(page, { engines: page.engines, keyboard: page.keyboardResults, records });
  return records;
}

// De-duplicated violation count for a page across all layers (page.violationCount).
function countViolations(page) {
  return pageFindings(page).length;
}

module.exports = {
  ENGINES,
  ENGINE_ORDER,
  RULE_ENGINES,
  RESULT_KEY,
  KEYBOARD_CRITERIA,
  hasEngineScan,
  hasKeyboardScan,
  dedupe,
  groupByCriterion,
  packEngineScan,
  engineRecords,
  keyboardRecords,
  pageFindings,
  countViolations,
};
