const pdfMake = require('pdfmake/build/pdfmake');
const pdfFonts = require('pdfmake/build/vfs_fonts');
const { buildFileName, downloadBlob } = require('./downloadUtil');
// Bundled as base64 by esbuild (see the .ttf loader in build.js).
const monoRegular = require('dejavu-fonts-ttf/ttf/DejaVuSansMono.ttf');
const monoBold = require('dejavu-fonts-ttf/ttf/DejaVuSansMono-Bold.ttf');
const { THEME, LEVEL_TINT, hash } = require('./reportTheme');

// pdfmake's vfs_fonts.js export shape has changed across versions; cover the
// possibilities defensively rather than assuming one bundler-friendly form.
pdfMake.vfs = pdfFonts.vfs || (pdfFonts.pdfMake && pdfFonts.pdfMake.vfs) || pdfFonts;
pdfMake.vfs['DejaVuSansMono.ttf'] = monoRegular;
pdfMake.vfs['DejaVuSansMono-Bold.ttf'] = monoBold;
pdfMake.fonts = {
  Roboto: {
    normal: 'Roboto-Regular.ttf',
    bold: 'Roboto-Medium.ttf',
    italics: 'Roboto-Italic.ttf',
    bolditalics: 'Roboto-MediumItalic.ttf',
  },
  // Monospace face for the keyboard focus log.
  Mono: {
    normal: 'DejaVuSansMono.ttf',
    bold: 'DejaVuSansMono-Bold.ttf',
    italics: 'DejaVuSansMono.ttf',
    bolditalics: 'DejaVuSansMono-Bold.ttf',
  },
};

const C = {
  purple: hash(THEME.purple),
  navy: hash(THEME.navy),
  rowAlt: hash(THEME.rowAlt),
  surface: hash(THEME.surface),
  text: hash(THEME.text),
  muted: hash(THEME.muted),
  border: hash(THEME.border),
  white: hash(THEME.white),
  placeholder: hash(THEME.placeholder),
};

// Placeholders are highlighted so an unfilled field is obvious before the report is sent.
function placeholder(text) {
  return { text, bold: true, background: C.placeholder, color: C.text };
}

// "Label: value" with a bold label.
function labeledLine(label, value, isPlaceholder) {
  return {
    text: [{ text: `${label}: `, bold: true }, isPlaceholder ? placeholder(value) : { text: value }],
    margin: [0, 0, 0, 7],
  };
}

const p = (text, extra) => ({ text, margin: [0, 0, 0, 5], ...extra });

function heading(text, sub) {
  return {
    text,
    bold: true,
    fontSize: sub ? 11.5 : 15,
    color: sub ? C.navy : C.purple,
    margin: [0, sub ? 12 : 18, 0, 6],
    headlineLevel: sub ? 2 : 1,
  };
}

const gridLayout = (fill) => ({
  hLineWidth: () => 0.6,
  vLineWidth: () => 0.6,
  hLineColor: () => C.border,
  vLineColor: () => C.border,
  // Navy header row, then body rows alternating between white and light grey. A cell's
  // own fillColor (the conformance tint) takes precedence over this.
  fillColor: (row) => (row === 0 ? C.navy : fill || (row % 2 === 0 ? C.rowAlt : null)),
  paddingLeft: () => 5,
  paddingRight: () => 5,
  paddingTop: () => 4,
  paddingBottom: () => 4,
});

// head: column titles; widths: percentages; rows: arrays of strings or
// { text, link?, fill? }.
function table(head, widths, rows, opts = {}) {
  const body = [
    head.map((h) => ({ text: h, bold: true, color: C.white })),
    ...rows.map((row) =>
      row.map((c) => {
        if (!c || typeof c !== 'object') return { text: String(c) };
        const out = { text: c.text };
        if (c.fill) out.fillColor = hash(c.fill);
        if (c.link) Object.assign(out, { link: c.link, color: C.purple, decoration: 'underline' });
        return out;
      })
    ),
  ];
  return {
    table: { headerRows: 1, dontBreakRows: true, widths: widths.map((w) => `${w}%`), body },
    layout: gridLayout(opts.fill),
    font: opts.mono ? 'Mono' : 'Roboto',
    fontSize: opts.fontSize || 9,
    margin: [0, 4, 0, 10],
  };
}

function criteriaTable(rows) {
  return table(
    ['Criteria', 'Conformance Level', 'Remarks and Explanations'],
    [35, 20, 45],
    rows.map((r) => [
      { text: r.criteria, link: r.link },
      { text: r.conformance, fill: LEVEL_TINT[r.conformance] },
      r.remarks || '',
    ])
  );
}

function focusLog(entry) {
  const out = [
    { text: 'Keyboard focus log', bold: true, margin: [0, 6, 0, 3] },
    ...entry.summary.map((text) => ({ text, margin: [0, 0, 0, 3] })),
  ];
  if (entry.rows.length) {
    out.push(
      table(
        ['#', 'Element', 'Role', 'Label', 'Focus indicator', 'Notes'],
        [6, 14, 11, 27, 18, 24],
        entry.rows.map((r) => [r.order, r.element, r.role, r.label, r.indicator, r.notes]),
        { mono: true, fill: C.surface, fontSize: 7 }
      )
    );
  }
  if (entry.traps.length) {
    out.push({ text: 'Keyboard traps detected', bold: true });
    out.push(table(['Element', 'Detail'], [45, 55], entry.traps.map((t) => [t.element, t.detail]), { fontSize: 8 }));
  }
  if (entry.unreachable.length) {
    out.push({ text: 'Interactive elements not reachable by Tab', bold: true });
    out.push(table(['Element', 'Why it was flagged'], [45, 55], entry.unreachable.map((u) => [u.element, u.detail]), { fontSize: 8 }));
    if (entry.unreachableOmitted) out.push({ text: `${entry.unreachableOmitted} further element(s) not listed.`, italics: true });
  }
  return out;
}

function pageAppendix(entry) {
  const out = [
    heading(entry.name, true),
    labeledLine('URL', entry.url),
    labeledLine('Scanned', entry.scannedAt),
  ];
  if (entry.screenshot) {
    out.push({ text: 'Screenshot at the time of the scan', bold: true, margin: [0, 6, 0, 3] });
    out.push({ image: entry.screenshot.dataUrl, width: Math.min(515, entry.screenshot.width), margin: [0, 0, 0, 6] });
  }
  out.push({ text: `Violations (${entry.violations.length})`, bold: true, margin: [0, 6, 0, 0] });
  if (entry.violations.length) {
    out.push(
      table(
        ['Criterion', 'Element', 'Issue', 'Detected by'],
        [12, 36, 32, 20],
        entry.violations.map((v) => [v.criterion, v.element, v.description, v.engines]),
        { fontSize: 8 }
      )
    );
  } else out.push({ text: 'No violations detected on this page.', margin: [0, 2, 0, 6] });
  if (entry.focus) out.push(...focusLog(entry.focus));
  return out;
}

function buildPdfDocDefinition(model) {
  const { meta } = model;
  const pageBreak = { text: '', pageBreak: 'after' };

  const content = [
    // Cover: plain white page, purple type.
    { text: meta.title, fontSize: 24, bold: true, color: C.purple, margin: [0, 40, 0, 4] },
    { text: meta.subtitle, fontSize: 13, italics: true, color: C.purple, margin: [0, 0, 0, 28] },
    ...model.coverFields.map((f) => ({ ...labeledLine(f.label, f.value, f.placeholder), fontSize: 10.5 })),
    pageBreak,

    heading('Applicable Standards/Guidelines'),
    p('This report covers the degree of conformance for the following accessibility standards/guidelines:'),
    table(['Standard/Guideline', 'Included in Report'], [60, 40], model.standards),

    heading('Terms'),
    p('The terms used in the Conformance Level information are defined as follows:'),
    { ul: model.terms.map(([term, definition]) => ({ text: [{ text: `${term}: `, bold: true }, definition], margin: [0, 0, 0, 3] })), margin: [0, 0, 0, 6] },
    ...(model.termsNote ? [p(model.termsNote, { italics: true })] : []),
    pageBreak,

    heading('WCAG 2.2 Report'),
    heading(model.tables[0].title, true),
    criteriaTable(model.tables[0].rows),
    heading(model.tables[1].title, true),
    criteriaTable(model.tables[1].rows),

    heading('Legal Disclaimer'),
    ...model.legalDisclaimer.map((text) => p(text)),
    p(model.trademarkNotice, { italics: true, color: C.muted }),
    pageBreak,

    heading('Appendix A: Evaluation Details'),
    { text: 'Pages tested', bold: true },
    table(
      ['Page', 'URL', 'Scanned', 'Violations'],
      [22, 43, 22, 13],
      model.pages.map((pg) => [pg.name, pg.url, pg.scannedAt, pg.violationCount])
    ),
    ...model.scope.facts.map(([label, value]) => ({ ...labeledLine(label, value), margin: [0, 0, 0, 3] })),
    { text: 'Out of scope', bold: true, margin: [0, 6, 0, 3] },
    p(model.scope.outOfScope),
    { text: 'Methodology', bold: true, margin: [0, 4, 0, 3] },
    ...model.evaluationMethods.map((text) => p(text)),
    table(
      ['Page', 'Rule engines', 'Keyboard scan'],
      [24, 46, 30],
      model.pages.map((pg) => [pg.name, pg.auto, pg.keyboard]),
      { fontSize: 8 }
    ),
    { text: 'Criteria by conformance level', bold: true },
    table(
      ['Conformance Level', 'Criteria'],
      [60, 40],
      model.summary.cards.map((card) => [{ text: card.label, fill: LEVEL_TINT[card.label] }, card.count])
    ),
  ];

  if (model.pageAppendix.length) {
    content.push(pageBreak);
    content.push(heading('Appendix B: Page Details'));
    content.push(p(
      'For each scanned page: every violation detected, and the sequential focus order recorded by the keyboard ' +
      'scan for consultant review of WCAG 2.4.3 Focus Order.'
    ));
    for (const entry of model.pageAppendix) content.push(...pageAppendix(entry));
  }

  return {
    pageSize: 'LETTER',
    pageMargins: [48, 44, 48, 46],
    info: { title: meta.docTitle, creator: meta.appName },
    defaultStyle: { font: 'Roboto', fontSize: 9.5, color: C.text, lineHeight: 1.15 },
    footer: (currentPage, pageCount) => ({
      text: `${meta.docTitle}  ·  ${meta.reportDate}  ·  Page ${currentPage} of ${pageCount}`,
      alignment: 'center',
      fontSize: 7.5,
      color: C.muted,
      margin: [48, 16, 48, 0],
    }),
    content,
  };
}

function exportPdf(model) {
  const docDefinition = buildPdfDocDefinition(model);
  return new Promise((resolve, reject) => {
    // pdfmake reports layout and font errors as unhandled promise rejections rather than
    // through its callback, so listen for one while the document is being built.
    const onRejection = (event) => {
      event.preventDefault();
      done(() => reject(event.reason instanceof Error ? event.reason : new Error(String(event.reason))));
    };
    const done = (finish) => {
      window.removeEventListener('unhandledrejection', onRejection);
      finish();
    };
    window.addEventListener('unhandledrejection', onRejection);
    try {
      pdfMake.createPdf(docDefinition).getBlob((blob) => {
        downloadBlob(blob, buildFileName(model, 'pdf'));
        done(resolve);
      });
    } catch (err) {
      done(() => reject(err));
    }
  });
}

module.exports = { buildPdfDocDefinition, exportPdf };
