// Wording for the Remarks and Explanations column, one entry per success criterion a
// scanning layer can report on:
//   works  - what the product does right, completing "The product ..."
//   fails  - what is failing, completing "The majority of ..."
//   impact - who is affected and how
// remarks.js assembles these into the three patterns:
//   Supports            "The product <works>."
//   Partially Supports  "In most instances, the product <works>. Exceptions include: ..."
//   Does Not Support    "The majority of <fails>. <impact>"
const CRITERIA_TEXT = {
  '1.1.1': {
    works: 'provides text alternatives for non-text content such as images, icons and image buttons',
    fails: 'non-text content (images, icons and image buttons) in the product lacks text alternatives',
    impact: 'Screen reader users cannot perceive the information or function conveyed by these elements.',
  },
  '1.2.1': {
    works: 'provides alternatives for prerecorded audio-only and video-only content',
    fails: 'prerecorded audio-only and video-only content in the product has no alternative',
    impact: 'Users who cannot see or hear the media do not get the information it carries.',
  },
  '1.2.2': {
    works: 'provides captions for prerecorded video that has audio',
    fails: 'prerecorded video in the product has no captions',
    impact: 'Deaf and hard-of-hearing users cannot access the spoken content.',
  },
  '1.3.1': {
    works: 'conveys structure and relationships such as headings, lists, tables and form labels programmatically',
    fails: 'structural content (headings, lists, tables and form fields) in the product is not marked up so that its relationships can be determined programmatically',
    impact: 'Screen reader users do not get the structure that sighted users see.',
  },
  '1.3.2': {
    works: 'presents content in an order that can be determined programmatically',
    fails: 'content in the product is presented in an order that cannot be determined programmatically',
    impact: 'Screen reader users encounter the content in a sequence that changes its meaning.',
  },
  '1.3.4': {
    works: 'works in both portrait and landscape orientation',
    fails: 'content in the product is locked to one display orientation',
    impact: 'Users whose device is mounted in a fixed orientation cannot use the content.',
  },
  '1.3.5': {
    works: 'identifies the purpose of form fields that collect personal information',
    fails: 'form fields that collect personal information in the product do not identify their purpose programmatically',
    impact: 'Users cannot rely on autofill or assistive technology to complete these fields.',
  },
  '1.4.1': {
    works: 'does not rely on color alone to convey information',
    fails: 'links and similar content in the product are distinguished from their surroundings by color alone',
    impact: 'Users who cannot distinguish colors miss this information.',
  },
  '1.4.2': {
    works: 'does not include audio that plays automatically for more than 3 seconds without a way to stop it',
    fails: 'audio in the product plays automatically with no way to stop or control it',
    impact: 'The audio can drown out a screen reader.',
  },
  '1.4.3': {
    works: 'presents text with sufficient contrast against its background',
    fails: 'text in the product does not have sufficient contrast against its background',
    impact: 'Users with low vision have difficulty reading this text.',
  },
  '1.4.4': {
    works: 'allows text to be resized up to 200% without loss of content or functionality',
    fails: 'pages in the product prevent text from being zoomed or resized',
    impact: 'Users with low vision cannot enlarge the text to read it.',
  },
  '1.4.12': {
    works: 'remains readable when users adjust text spacing',
    fails: 'text in the product has spacing fixed in a way that users cannot override',
    impact: 'Users who need wider spacing to read cannot apply it.',
  },
  '2.1.1': {
    works: 'can be operated with a keyboard',
    fails: 'interactive elements in the product cannot be operated with a keyboard',
    impact: 'Keyboard-only users cannot reach or operate this functionality.',
  },
  '2.1.2': {
    works: 'lets keyboard focus move freely into and out of every component',
    fails: 'components in the product trap keyboard focus',
    impact: 'Keyboard-only users cannot move past these components to the rest of the page.',
  },
  '2.2.1': {
    works: 'does not impose time limits that users cannot adjust',
    fails: 'pages in the product enforce a time limit or automatic refresh that users cannot adjust',
    impact: 'Users who need more time lose their place or their work.',
  },
  '2.2.2': {
    works: 'does not include moving, blinking or scrolling content that users cannot pause',
    fails: 'moving or blinking content in the product cannot be paused, stopped or hidden',
    impact: 'Users are distracted or blocked by motion they cannot stop.',
  },
  '2.4.1': {
    works: 'provides a mechanism to bypass blocks of content that repeat across pages',
    fails: 'pages in the product provide no mechanism, such as a skip link, to bypass repeated blocks of content',
    impact: 'Keyboard and screen reader users must move through the same repeated content before reaching the main content.',
  },
  '2.4.2': {
    works: 'gives each page a title that describes its topic or purpose',
    fails: 'pages in the product have no descriptive title',
    impact: 'Users cannot identify the page or tell open pages apart.',
  },
  '2.4.4': {
    works: 'ensures that the purpose of links can be determined from the link text alone or in combination with the surrounding context',
    fails: 'links in the product have no accessible name that describes their purpose',
    impact: 'Screen reader users cannot tell where these links lead.',
  },
  '2.4.7': {
    works: 'shows a visible focus indicator on elements that receive keyboard focus',
    fails: 'focusable elements in the product show no visible focus indicator',
    impact: 'Keyboard users cannot tell which element is active.',
  },
  '2.4.11': {
    works: 'keeps the element that has keyboard focus at least partly visible',
    fails: 'focusable elements in the product are entirely hidden behind other content when they receive focus',
    impact: 'Keyboard users cannot see what is focused.',
  },
  '2.5.3': {
    works: 'includes the visible label text in the accessible name of its controls',
    fails: 'controls in the product have an accessible name that does not contain their visible label',
    impact: 'Speech-input users cannot activate these controls by saying what they see.',
  },
  '2.5.8': {
    works: 'provides pointer targets that are at least 24 by 24 CSS pixels or sufficiently spaced',
    fails: 'pointer targets in the product are smaller than 24 by 24 CSS pixels without sufficient spacing',
    impact: 'Users with limited dexterity have difficulty activating them accurately.',
  },
  '3.1.1': {
    works: 'identifies the default language of each page programmatically',
    fails: 'pages in the product do not identify their language programmatically',
    impact: 'Screen readers may read the content with the wrong pronunciation.',
  },
  '3.1.2': {
    works: 'identifies passages in a different language programmatically',
    fails: 'passages in another language in the product are not identified correctly',
    impact: 'Screen readers may read these passages with the wrong pronunciation.',
  },
  '3.3.2': {
    works: 'provides labels or instructions for form fields',
    fails: 'form fields in the product have no label or instructions',
    impact: 'Users do not know what information to enter.',
  },
  '4.1.2': {
    works: 'exposes the name, role and value of user interface components to assistive technology',
    fails: 'user interface components in the product do not expose a name, role or value to assistive technology',
    impact: 'Assistive technology users cannot identify or operate these components.',
  },
};

// For a criterion an engine covers but that has no entry above.
function textFor(sc, name) {
  return CRITERIA_TEXT[sc] || {
    works: `meets ${sc} ${name}`,
    fails: `content in the product does not meet ${sc} ${name}`,
    impact: 'Users who depend on this requirement may be unable to perceive or operate the affected content.',
  };
}

module.exports = { CRITERIA_TEXT, textFor };
