// axe-core -> WCAG success criteria mapping.
//
// axe-core tags every rule with the success criteria it tests ("wcag111" = 1.1.1,
// "wcag1410" = 1.4.10). The mapping is read from those tags at scan time instead of a
// hand-maintained rule list, so a violation can never be dropped because its rule was
// missing from a table, and coverage always matches the axe-core version that ran.
//
// This is also how the WCAG 2.2 additions are handled: after each scan the panel stores
// which criteria the running axe-core build has at least one rule for (`coveredSc`).
// Any criterion with no rule - currently 2.4.11, 2.5.7, 3.2.6, 3.3.7 and 3.3.8 - resolves
// to "Not Evaluated" in conformance.js unless the keyboard scan covers it.

const { WCAG22_ALL } = require('./wcag');

const TAG_TO_SC = {};
for (const { sc } of WCAG22_ALL) TAG_TO_SC[`wcag${sc.replace(/\./g, '')}`] = sc;

function scsForTags(tags) {
  const out = [];
  for (const tag of tags || []) {
    const sc = TAG_TO_SC[tag];
    if (sc && !out.includes(sc)) out.push(sc);
  }
  return out;
}

// ruleTags: array of tag arrays, one per rule axe-core ran.
// Only used for sessions saved before the multi-engine scan (storage.js migration).
function coveredScFromRuleTags(ruleTags) {
  const out = new Set();
  for (const tags of ruleTags || []) for (const sc of scsForTags(tags)) out.add(sc);
  return [...out].sort();
}

module.exports = { TAG_TO_SC, scsForTags, coveredScFromRuleTags };
