// Rule-engine scan: axe-core, IBM Equal Access and HTML CodeSniffer, run one after the
// other against the live DOM.
//
// This function is injected into the scanned page via chrome.scripting.executeScript's
// `func` option, after the three engine files in content/vendor/ have been injected (so
// the globals `axe`, `ace` and `HTMLCS` exist there). It must stay self-contained - no
// references to anything outside its own body except those page globals and its own
// parameter - because the browser serializes it by source text and re-executes it in the
// target page's isolated world, not by calling it in this module's closure.
//
// All three engines run in the same world, so every finding can be tied to the actual DOM
// element and given the same element key. That shared key is what lets lib/findings.js
// recognise "three engines flagged this one element" as a single finding.
//
// Returns interned tables to keep the message small:
//   elements: [[key, snippet], ...]
//   rules:    [[engine, ruleId, description], ...]
//   records:  [[successCriterion, elementIndex, ruleIndex, kind], ...]   kind: 'v' | 'r'
// 'v' is a definite failure; 'r' is "needs review" (axe-core incomplete, IBM potential).
async function engineScanInPage(opts) {
  const AXE = 'axe-core';
  const IBM = 'IBM Equal Access';
  const HTMLCS_NAME = 'HTML CodeSniffer';

  const elements = [];
  const elementIndex = new Map();
  const rules = [];
  const ruleIndex = new Map();
  const records = [];
  const covered = {};
  const versions = {};
  const errors = {};

  const clip = (str, max) => {
    const s = String(str || '').replace(/\s+/g, ' ').trim();
    return s.length > max ? `${s.slice(0, max - 1)}…` : s;
  };

  // Unique, stable path for an element. keyboardScan.js builds the same key, so keyboard
  // findings can merge with engine findings on the same element. Keep the two in sync.
  const idCounts = new Map();
  function idIsUnique(root, id) {
    let perRoot = idCounts.get(root);
    if (!perRoot) idCounts.set(root, (perRoot = new Map()));
    if (!perRoot.has(id)) {
      let count = 0;
      try {
        count = root.querySelectorAll(`#${CSS.escape(id)}`).length;
      } catch (err) {
        count = 0;
      }
      perRoot.set(id, count);
    }
    return perRoot.get(id) === 1;
  }
  function keyOf(el) {
    if (!el || el.nodeType !== 1 || el === document.documentElement) return 'html';
    const parts = [];
    let node = el;
    while (node && node.nodeType === 1) {
      const root = node.getRootNode();
      const parent = node.parentElement;
      let part = node.tagName.toLowerCase();
      let anchored = false;
      if (node.id && idIsUnique(root, node.id)) {
        part = `#${CSS.escape(node.id)}`;
        anchored = true;
      } else if (parent) {
        const same = Array.from(parent.children).filter((c) => c.tagName === node.tagName);
        if (same.length > 1) part += `:nth-of-type(${same.indexOf(node) + 1})`;
      }
      parts.unshift(part);
      if (anchored || !parent) {
        if (root && root.host) {
          parts.unshift('>>>');
          node = root.host;
          continue;
        }
        break;
      }
      node = parent;
    }
    return parts.join(' > ').replace(/ > >>> > /g, ' >>> ');
  }

  function internElement(el, fallbackKey, fallbackSnippet) {
    const isEl = el && el.nodeType === 1;
    const key = isEl || !fallbackKey ? keyOf(el) : fallbackKey;
    if (!elementIndex.has(key)) {
      let snippet = fallbackSnippet || '';
      if (isEl) {
        try {
          snippet = el.cloneNode(false).outerHTML;
        } catch (err) {
          snippet = `<${el.tagName.toLowerCase()}>`;
        }
      } else if (key === 'html') snippet = '(whole page)';
      elementIndex.set(key, elements.length);
      elements.push([key, clip(snippet, 140)]);
    }
    return elementIndex.get(key);
  }

  function internRule(engine, ruleId, description) {
    const id = `${engine}|${ruleId}`;
    if (!ruleIndex.has(id)) {
      ruleIndex.set(id, rules.length);
      rules.push([engine, ruleId, clip(description, 180)]);
    }
    return ruleIndex.get(id);
  }

  const scFromAxeTags = (tags) =>
    (tags || [])
      .map((t) => /^wcag(\d)(\d)(\d+)$/.exec(t))
      .filter(Boolean)
      .map((m) => `${m[1]}.${m[2]}.${m[3]}`);

  // ---------- axe-core ----------
  try {
    versions[AXE] = axe.version;
    const results = await axe.run(document, {
      resultTypes: ['violations', 'incomplete'],
      runOnly: { type: 'tag', values: opts.axeTags },
      elementRef: true,
    });
    const add = (list, kind) => {
      for (const v of list) {
        const scs = scFromAxeTags(v.tags);
        if (scs.length === 0) continue;
        const rule = internRule(AXE, v.id, v.help);
        for (const node of v.nodes) {
          // Nodes inside iframes have no element reference here; axe's selector chain
          // identifies them instead.
          const target = (node.target || []).map((t) => (Array.isArray(t) ? t.join(' ') : t)).join(' >>> ');
          const inFrame = (node.target || []).length > 1;
          const el = internElement(inFrame ? null : node.element, inFrame || !node.element ? `frame: ${target}` : '', node.html);
          for (const sc of scs) records.push([sc, el, rule, kind]);
        }
      }
    };
    add(results.violations, 'v');
    add(results.incomplete, 'r');
    // Coverage = criteria this axe-core build has a rule for. Experimental and deprecated
    // rules carry WCAG tags but are excluded from tag-based runs, so they don't count.
    const set = new Set();
    for (const r of axe.getRules(opts.axeTags)) {
      if (r.tags.includes('experimental') || r.tags.includes('deprecated')) continue;
      for (const sc of scFromAxeTags(r.tags)) set.add(sc);
    }
    covered[AXE] = [...set];
  } catch (err) {
    errors[AXE] = String((err && err.message) || err);
  }

  // ---------- IBM Equal Access ----------
  try {
    versions[IBM] = opts.versions[IBM];
    const checker = new ace.Checker();
    const ruleMap = checker.engine.ruleMap;
    const POLICY = 'WCAG_2_2';
    // Criteria each rule is a VIOLATION-level check for under the WCAG 2.2 policy.
    const scForRule = {};
    const set = new Set();
    for (const id of Object.keys(ruleMap)) {
      const scs = [];
      for (const rs of ruleMap[id].rulesets || []) {
        if (rs.level === 'VIOLATION' && (rs.id || []).includes(POLICY)) scs.push(...(rs.num || []));
      }
      scForRule[id] = [...new Set(scs)];
      // A rule only gives coverage if it can report a definite failure; rules that can
      // only say "potential" or "manual" never decide a criterion on their own.
      if (/\bRuleFail\b/.test(String(ruleMap[id].run))) for (const sc of scForRule[id]) set.add(sc);
    }
    covered[IBM] = [...set];

    const report = await checker.check(document, [POLICY]);
    for (const res of report.results || []) {
      const value = res.value || [];
      if (value[0] !== 'VIOLATION') continue;
      const kind = value[1] === 'FAIL' ? 'v' : value[1] === 'POTENTIAL' ? 'r' : '';
      if (!kind) continue;
      const scs = scForRule[res.ruleId] || [];
      if (scs.length === 0) continue;
      const xpath = (res.path && res.path.dom) || '';
      let node = res.node && res.node.nodeType === 1 ? res.node : null;
      if (!node && xpath) {
        try {
          node = document.evaluate(xpath, document, null, XPathResult.FIRST_ORDERED_NODE_TYPE, null).singleNodeValue;
        } catch (err) {
          node = null;
        }
      }
      const pageLevel = xpath === '/html[1]' || xpath === '';
      const el = internElement(pageLevel ? document.documentElement : node, node || pageLevel ? '' : `xpath: ${xpath}`, res.snippet);
      const messages = (ruleMap[res.ruleId].messages || {})['en-US'] || {};
      const rule = internRule(IBM, res.ruleId, messages.group || res.message);
      for (const sc of scs) records.push([sc, el, rule, kind]);
    }
  } catch (err) {
    errors[IBM] = String((err && err.message) || err);
  }

  // ---------- HTML CodeSniffer ----------
  try {
    versions[HTMLCS_NAME] = opts.versions[HTMLCS_NAME];
    const scFromCode = (code) => {
      const m = /Guideline\d+_\d+\.(\d+)_(\d+)_(\d+)/.exec(code || '');
      return m ? `${m[1]}.${m[2]}.${m[3]}` : '';
    };
    // Coverage = WCAG2AA sniffs whose code can raise an ERROR. Most HTML CodeSniffer
    // sniffs only raise warnings and notices ("check that..."), which are prompts for a
    // human rather than automated determinations.
    const set = new Set();
    const standard = globalThis.HTMLCS_WCAG2AA;
    for (const group of (standard && standard.sniffs) || []) {
      for (const name of (group && group.include) || []) {
        const sniff = globalThis[`HTMLCS_${group.standard}_Sniffs_${name.replace(/\./g, '_')}`];
        const sc = scFromCode(name);
        if (!sniff || !sc) continue;
        const source = Object.keys(sniff).map((k) => (typeof sniff[k] === 'function' ? String(sniff[k]) : '')).join('\n');
        if (source.includes('HTMLCS.ERROR')) set.add(sc);
      }
    }
    covered[HTMLCS_NAME] = [...set];

    await new Promise((resolve, reject) => {
      HTMLCS.process('WCAG2AA', document, resolve, () => reject(new Error('HTML CodeSniffer could not process the page.')));
    });
    for (const msg of HTMLCS.getMessages()) {
      if (msg.type !== HTMLCS.ERROR) continue;
      const sc = scFromCode(msg.code);
      if (!sc) continue;
      const el = internElement(msg.element && msg.element.nodeType === 1 ? msg.element : document.documentElement);
      const ruleId = String(msg.code).split('.').slice(4).join('.') || msg.code;
      records.push([sc, el, internRule(HTMLCS_NAME, ruleId, msg.msg), 'v']);
    }
  } catch (err) {
    errors[HTMLCS_NAME] = String((err && err.message) || err);
  }

  return { url: location.href, title: document.title, versions, errors, covered, elements, rules, records };
}

const AXE_RUN_ONLY_TAGS = ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa'];

// Injected, in this order, before engineScanInPage runs.
const ENGINE_FILES = ['content/vendor/axe.min.js', 'content/vendor/ace.js', 'content/vendor/HTMLCS.js'];

module.exports = { engineScanInPage, AXE_RUN_ONLY_TAGS, ENGINE_FILES };
