const { BUCKETS } = require('./conformance');
const { ENGINES, RULE_ENGINES } = require('./findings');
const { textFor } = require('./criteriaText');

// Builds the Remarks and Explanations text for one criterion from its findings, in the
// style of a professionally written ACR:
//   Supports            one sentence on what the product does right
//   Partially Supports  "In most instances, ... Exceptions include:" then one bullet per failure
//   Does Not Support    "The majority of ..." then the impact, counts and failing checks
// Remarks may contain line breaks; bullets start with "• ".

function capitalize(str) {
  if (!str) return str;
  return str.charAt(0).toUpperCase() + str.slice(1);
}

function joinWithAnd(list) {
  if (list.length <= 1) return list[0] || '';
  if (list.length === 2) return `${list[0]} and ${list[1]}`;
  return `${list.slice(0, -1).join(', ')}, and ${list[list.length - 1]}`;
}

function uniquePreserveOrder(arr) {
  return [...new Set(arr)];
}

const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

// Failure descriptions for keyboard-scan findings. `n` is the instance count.
const KEYBOARD_FINDINGS = {
  '2.1.1': (n) => `${plural(n, 'interactive element', 'interactive elements')} cannot be reached using the Tab key`,
  '2.1.2': (n) => `${plural(n, 'component traps', 'components trap')} keyboard focus so that it cannot be moved away using the Tab key`,
  '2.4.1': () => 'No skip link was found to let keyboard users bypass repeated content',
  '2.4.7': (n) => `${plural(n, 'focusable element shows', 'focusable elements show')} no visible focus indicator`,
  '2.4.11': (n) => `${plural(n, 'focusable element is', 'focusable elements are')} completely covered by other content when focused`,
};

const MAX_LISTED_CHECKS = 4;

const NOT_EVALUATED = 'This criterion has not been evaluated.';
const NOT_APPLICABLE = 'This criterion does not apply to the product.';
const FOCUS_ORDER_NOTE = 'Focus order logged. Manual review required to confirm logical sequence.';

// The distinct failures behind a criterion's findings, most frequent first. Engines word
// the same problem differently, so each finding is described once, in the words of the
// first engine (axe-core, then IBM, then HTML CodeSniffer) that reported it.
function listFailures(sc, records) {
  const failures = [];
  const keyboardCount = records.filter((r) => r.engineSource.includes(ENGINES.KEYBOARD)).length;
  if (keyboardCount > 0 && KEYBOARD_FINDINGS[sc]) failures.push({ text: KEYBOARD_FINDINGS[sc](keyboardCount), count: keyboardCount, keyboard: true });

  const tally = new Map();
  for (const r of records) {
    const rule = r.rules.find((x) => RULE_ENGINES.includes(x.engine));
    if (!rule) continue;
    const text = (rule.description || '').trim().replace(/\.$/, '');
    if (text) tally.set(text, (tally.get(text) || 0) + 1);
  }
  const ranked = [...tally.entries()].sort((a, b) => b[1] - a[1]).map(([text, count]) => ({ text, count }));
  const shown = ranked.slice(0, MAX_LISTED_CHECKS);
  const more = ranked.length - shown.length;
  return { failures: [...failures, ...shown], more };
}

// Keyboard descriptions already carry their count; engine checks get it appended.
const describeFailure = (f) => (f.keyboard ? f.text : `${f.text} (${plural(f.count, 'instance', 'instances')})`);

function buildRemarks(criterionResult) {
  // A consultant override leads the remarks; whatever the scans found follows it.
  if (criterionResult.overrideNote) {
    const note = criterionResult.overrideNote.trim().replace(/[.\s]+$/, '');
    const auto = criterionResult.autoBucket;
    const automated = auto === BUCKETS.NOT_EVALUATED ? '' : buildRemarks({ ...criterionResult, bucket: auto, overrideNote: '' });
    return [`Consultant determination: ${note}.`, automated && `Automated results: ${automated}`].filter(Boolean).join(' ');
  }

  const {
    sc, name, bucket, records = [], pageCounts = [], instanceCount = 0, totalPages = 0,
    incompleteCount = 0, keyboardPages = 0,
  } = criterionResult;

  if (bucket === BUCKETS.NOT_EVALUATED) {
    return sc === '2.4.3' && keyboardPages > 0 ? `${NOT_EVALUATED} ${FOCUS_ORDER_NOTE}` : NOT_EVALUATED;
  }
  if (bucket === BUCKETS.NOT_APPLICABLE) {
    return NOT_APPLICABLE;
  }

  const text = textFor(sc, name);

  // axe-core ("incomplete") and IBM Equal Access ("potential") report some elements as
  // needing review, e.g. text over a background image. They are not violations, but the
  // consultant has to look at them.
  const reviewStr = incompleteCount > 0
    ? `${plural(incompleteCount, 'element', 'elements')} could not be determined automatically and ${incompleteCount === 1 ? 'requires' : 'require'} manual review.`
    : '';

  if (bucket === BUCKETS.SUPPORTS) {
    return [`The product ${text.works}.`, reviewStr].filter(Boolean).join(' ');
  }

  const { failures, more } = listFailures(sc, records);
  const moreStr = more > 0 ? `and ${plural(more, 'other failing check', 'other failing checks')}` : '';
  const listed = pageCounts.map((p) => `${p.name} (${p.count})`);
  const pageStr = `Pages affected (${pageCounts.length} of ${totalPages} scanned): ${joinWithAnd(listed)}.`;
  const countStr = `${plural(instanceCount, 'instance was', 'instances were')} detected.`;
  const engines = uniquePreserveOrder(records.flatMap((r) => r.engineSource));
  const detectedBy = engines.length ? `Detected by: ${engines.join(', ')}.` : '';
  const closing = [pageStr, countStr, detectedBy, reviewStr].filter(Boolean).join(' ');

  if (bucket === BUCKETS.PARTIALLY) {
    const bullets = failures.map((f) => `• ${capitalize(describeFailure(f))}.`);
    if (moreStr) bullets.push(`• ${capitalize(moreStr)}.`);
    return [
      `In most instances, the product ${text.works}. Exceptions include:`,
      ...bullets,
      `${text.impact} ${closing}`,
    ].join('\n');
  }

  // Does Not Support
  const checks = [...failures.map(describeFailure), moreStr].filter(Boolean).join('; ');
  return [
    `The majority of ${text.fails}. ${text.impact}`,
    `${capitalize(countStr.slice(0, -1))}: ${checks}.`,
    [pageStr, detectedBy, reviewStr].filter(Boolean).join(' '),
  ].join(' ');
}

module.exports = { FOCUS_ORDER_NOTE, NOT_EVALUATED, NOT_APPLICABLE, buildRemarks };
