// Session persistence. One session lives in localStorage, so it survives navigation,
// closing and reopening the panel, and browser restarts, until the user clears it.
//
// Session object:
//   {
//     version, sessionId, startedAt, updatedAt,
//     productName, productVersion, preparedBy, company, reportDate,
//     productDescription, contactInfo, notes, scrollPosition,
//     notApplicable: [criterion, ...], doesNotSupport: { criterion: note },   // consultant overrides
//     keptForDomains: [domain, ...],   // sites where the user chose to keep scan data from another site
//     pages: [{
//       pageId, name, url, scannedAt,
//       axeResults: [], ibmResults: [], codesnifferResults: [],   // [criterion, elementIndex, ruleIndex]
//       keyboardResults: {},                                      // keyboardScanInPage result, {} until run
//       violationCount,                                           // de-duplicated, all layers
//       environment,                                              // e.g. "Chrome 141 on Windows"
//       engines: { ranAt, versions, errors, coveredSc, review, elements, rules } | null,
//       screenshot: { dataUrl, width, height } | null,
//     }]
//   }
// The three per-engine result arrays index into engines.elements / engines.rules; see
// findings.js for how they are read back and de-duplicated.

const { scsForTags } = require('./axeMapping');
const { countViolations } = require('./findings');

const STORAGE_KEY = 'vpat_session_v2';
const SCHEMA_VERSION = 4;

function nowIso() {
  return new Date().toISOString();
}

function genId() {
  if (typeof crypto !== 'undefined' && crypto.randomUUID) return crypto.randomUUID();
  return `id_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
}

// "Prepared by" is remembered across sessions so it only has to be typed once.
const PREPARED_BY_KEY = 'vpat_last_prepared_by';

function loadLastPreparedBy() {
  try {
    return localStorage.getItem(PREPARED_BY_KEY) || '';
  } catch (err) {
    return '';
  }
}

function rememberPreparedBy(name) {
  try {
    localStorage.setItem(PREPARED_BY_KEY, name);
  } catch (err) {
    // ignore
  }
}

function createEmptySession() {
  const ts = nowIso();
  return {
    version: SCHEMA_VERSION,
    sessionId: genId(),
    startedAt: ts,
    updatedAt: ts,
    // Report settings; they feed the cover page of the generated report.
    productName: '',
    productVersion: '',
    preparedBy: loadLastPreparedBy(),
    company: '',
    reportDate: '', // yyyy-mm-dd, or '' for "today"
    productDescription: '',
    contactInfo: '',
    notes: '',
    scrollPosition: 0,
    pages: [],
    // Success criteria the consultant has explicitly marked Not Applicable.
    notApplicable: [],
    // Consultant overrides to Does Not Support: { criterion: note }.
    doesNotSupport: {},
  };
}

function createPage(name, url) {
  return {
    pageId: genId(),
    name: name || 'Untitled page',
    url: url || '',
    scannedAt: null,
    axeResults: [],
    ibmResults: [],
    codesnifferResults: [],
    keyboardResults: {},
    violationCount: 0,
    environment: '',
    engines: null,
    screenshot: null,
  };
}

// v2 sessions stored axe-core results per rule with only a node count. They are carried
// over with the same counts; the individual elements were never recorded, so those
// findings can't merge with other engines until the page is re-scanned.
function migrateV2(session) {
  for (const page of session.pages || []) {
    const old = page.axe;
    delete page.axe;
    page.auto = null;
    if (!old) continue;
    const elements = [];
    const rules = [];
    const findings = [];
    (old.violations || []).forEach((v) => {
      const rule = rules.push(['axe-core', v.id, v.help || v.id]) - 1;
      for (let n = 0; n < (v.nodeCount || 0); n += 1) {
        const el = elements.push([`legacy:${v.id}:${n}`, '(element not recorded - re-scan this page)']) - 1;
        for (const sc of scsForTags(v.tags)) findings.push([sc, el, [rule]]);
      }
    });
    const review = {};
    for (const v of old.incomplete || []) {
      for (const sc of scsForTags(v.tags)) review[sc] = (review[sc] || 0) + (v.nodeCount || 0);
    }
    page.auto = {
      ranAt: old.ranAt,
      url: old.url || page.url,
      versions: { 'axe-core': old.axeVersion },
      errors: {},
      coveredSc: { 'axe-core': old.coveredSc || [] },
      elements,
      rules,
      findings,
      review,
    };
  }
  session.version = 3;
}

// v3 kept one merged findings list per page (page.auto) and page.keyboard. v4 stores
// each engine's results separately under the session structure documented above.
const V3_RESULT_KEY = { 'axe-core': 'axeResults', 'IBM Equal Access': 'ibmResults', 'HTML CodeSniffer': 'codesnifferResults' };
function migrateV3(session) {
  session.sessionId = session.sessionId || genId();
  session.startedAt = session.startedAt || session.createdAt || nowIso();
  delete session.createdAt;
  delete session.openFocusLogs;
  session.pages = (session.pages || []).map((old) => {
    const page = createPage(old.name, old.url);
    page.pageId = old.id || page.pageId;
    const auto = old.auto;
    if (auto) {
      page.engines = {
        ranAt: auto.ranAt,
        versions: auto.versions || {},
        errors: auto.errors || {},
        coveredSc: auto.coveredSc || {},
        review: auto.review || {},
        elements: auto.elements || [],
        rules: auto.rules || [],
      };
      for (const [sc, el, ruleIdxs] of auto.findings || []) {
        for (const r of ruleIdxs) {
          const key = V3_RESULT_KEY[(page.engines.rules[r] || [])[0]];
          if (key) page[key].push([sc, el, r]);
        }
      }
    }
    if (old.keyboard) page.keyboardResults = old.keyboard;
    page.scannedAt = [auto && auto.ranAt, old.keyboard && old.keyboard.ranAt].filter(Boolean).sort().pop() || null;
    page.violationCount = countViolations(page);
    return page;
  });
  session.version = 4;
}

function loadSession() {
  let raw;
  try {
    raw = localStorage.getItem(STORAGE_KEY);
  } catch (err) {
    return null;
  }
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw);
    if (parsed && parsed.version === 2) migrateV2(parsed);
    if (parsed && parsed.version === 3) migrateV3(parsed);
    if (!parsed || parsed.version !== SCHEMA_VERSION) return null;
    if (!Array.isArray(parsed.pages)) parsed.pages = [];
    if (!Array.isArray(parsed.notApplicable)) parsed.notApplicable = [];
    if (!parsed.doesNotSupport || typeof parsed.doesNotSupport !== 'object') parsed.doesNotSupport = {};
    return parsed;
  } catch (err) {
    return null;
  }
}

// Returns false when the write failed (localStorage quota), so the panel can tell the
// user their latest results are not persisted instead of showing a stale "last saved".
// `touch: false` saves without moving updatedAt (used for scroll position), so that
// timestamp keeps meaning "last time the session's content changed".
function saveSession(session, { touch = true } = {}) {
  const previous = session.updatedAt;
  if (touch) session.updatedAt = nowIso();
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(session));
    return true;
  } catch (err) {
    console.error('Failed to save session to localStorage', err);
    session.updatedAt = previous;
    return false;
  }
}

const STALE_AFTER_MS = 7 * 24 * 60 * 60 * 1000;

// A session with scanned pages that has not been modified for 7 days.
function isStale(session, now = Date.now()) {
  return session.pages.length > 0 && now - new Date(session.updatedAt).getTime() > STALE_AFTER_MS;
}

function clearSession() {
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch (err) {
    // ignore
  }
}

// Site domain of a page URL, without "www." ("https://www.hint.app/#features" -> "hint.app").
// '' for URLs without a web host (chrome://, about:, file:).
function domainOf(url) {
  try {
    const { protocol, hostname } = new URL(url);
    if (protocol !== 'http:' && protocol !== 'https:') return '';
    return hostname.replace(/^www\./, '');
  } catch (err) {
    return '';
  }
}

// Domain of the most recently scanned page, '' when nothing has been scanned.
function lastScannedDomain(session) {
  const scanned = (session.pages || []).filter((p) => p.scannedAt && p.url);
  if (scanned.length === 0) return '';
  const last = scanned.reduce((a, b) => (b.scannedAt > a.scannedAt ? b : a));
  return domainOf(last.url);
}

// Product name for the report: the Report settings entry, else the scanned site's domain.
function reportProductName(session) {
  if ((session.productName || '').trim()) return session.productName.trim();
  const first = (session.pages || []).find((p) => domainOf(p.url));
  return first ? domainOf(first.url) : '';
}

module.exports = {
  STORAGE_KEY,
  SCHEMA_VERSION,
  createEmptySession,
  createPage,
  loadSession,
  saveSession,
  clearSession,
  rememberPreparedBy,
  isStale,
  domainOf,
  lastScannedDomain,
  reportProductName,
  genId,
  nowIso,
};
