function formatTimestamp(iso) {
  try {
    return new Date(iso).toLocaleString();
  } catch (err) {
    return iso;
  }
}

const plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;

// --- modal dialog ---
// window.confirm()/prompt() are unreliable inside extension side panels and sidebars, so
// confirmations, choices and the page-name prompt all use this in-panel modal.
// Resolves to { value, text } for the chosen button, or null if dismissed.
function showDialog({ message, input, buttons }) {
  return new Promise((resolve) => {
    el.dialogMessage.textContent = message;
    el.dialogField.hidden = !input;
    if (input) {
      el.dialogInputLabel.textContent = input.label;
      el.dialogInput.value = input.value || '';
    }
    el.dialogActions.innerHTML = '';
    const finish = (result) => {
      el.dialog.removeEventListener('cancel', onCancel);
      el.dialogForm.removeEventListener('submit', onSubmit);
      if (el.dialog.open) el.dialog.close();
      resolve(result);
    };
    const choose = (value) => finish(value === null ? null : { value, text: el.dialogInput.value.trim() });
    const onCancel = () => finish(null);
    const primary = buttons.find((b) => b.primary) || buttons[0];
    // Enter in the text field acts as the primary button.
    const onSubmit = (e) => {
      e.preventDefault();
      choose(primary.value);
    };
    for (const b of buttons) {
      const btn = document.createElement('button');
      btn.type = 'button';
      btn.className = `btn${b.primary ? ' btn-primary' : ''}${b.danger ? ' btn-danger' : ''}`;
      btn.textContent = b.label;
      btn.addEventListener('click', () => choose(b.value));
      el.dialogActions.appendChild(btn);
    }
    el.dialogActions.classList.toggle('stacked', buttons.length > 2);
    el.dialog.addEventListener('cancel', onCancel);
    el.dialogForm.addEventListener('submit', onSubmit);
    el.dialog.showModal();
    if (input) {
      el.dialogInput.focus();
      el.dialogInput.select();
    } else el.dialogActions.lastElementChild.focus();
  });
}

async function confirmAction(message, okLabel, danger) {
  const result = await showDialog({
    message,
    buttons: [{ label: okLabel || 'OK', value: true, primary: !danger, danger }, { label: 'Cancel', value: null }],
  });
  return !!result;
}

// --- persistence ---

function persist(options) {
  saveNote = '';
  saveFailed = !storage.saveSession(session, options);
  // Screenshots are by far the largest thing stored; give them up before losing a save.
  if (saveFailed && session.pages.some((p) => p.screenshot)) {
    for (const p of session.pages) p.screenshot = null;
    saveFailed = !storage.saveSession(session, options);
    if (!saveFailed) saveNote = ' Screenshots were dropped to fit browser storage.';
  }
  if (!saveFailed) hasPersisted = true;
  renderLastSaved();
}

function renderLastSaved() {
  el.lastSaved.classList.toggle('save-failed', saveFailed);
  if (saveFailed) {
    el.lastSaved.textContent = 'NOT SAVED - browser storage is full. Generate the VPAT now, then remove pages or clear the session.';
  } else {
    el.lastSaved.textContent = hasPersisted ? `Last saved: ${formatTimestamp(session.updatedAt)}.${saveNote}` : 'Not saved yet';
  }
}

// --- current page ---

async function getActiveTab() {
  const tabs = await browser.tabs.query({ active: true, currentWindow: true });
  return tabs && tabs[0];
}

async function refreshActiveTab() {
  try {
    activeTab = await getActiveTab();
  } catch (err) {
    activeTab = null;
  }
  el.currentUrl.textContent = (activeTab && activeTab.url) || 'No page available to scan';
}

// --- session list ---

function keyboardIssueCount(kb) {
  return keyboardRecords(kb).length;
}

function failedEngines(page) {
  return Object.keys((page.engines && page.engines.errors) || {});
}

// Each badge carries its meaning in text and a symbol, never in colour alone.
function pageBadges(page) {
  const badges = [];
  if (hasEngineScan(page)) {
    const count = pageFindings(page).filter((r) => r.engineSource.some((e) => RULE_ENGINES.includes(e))).length;
    badges.push(count === 0
      ? { cls: 'clean', text: '✓ Engines: clean' }
      : { cls: 'violations', text: `✕ Engines: ${count}` });
    const failed = failedEngines(page);
    if (failed.length) badges.push({ cls: 'violations', text: `⚠ ${failed.join(', ')} did not run` });
  }
  if (hasKeyboardScan(page)) {
    const issues = keyboardIssueCount(page.keyboardResults);
    badges.push({ cls: 'keyboard', text: issues ? `⌨ Keyboard: ${issues}` : '⌨ Keyboard: clean' });
  }
  if (page.screenshot) badges.push({ cls: 'pending', text: 'Screenshot saved' });
  return badges;
}

function stopLine(stop) {
  const issues = [];
  if (stop.ind === 'missing') issues.push('no visible focus indicator');
  if (stop.ind === 'unknown') issues.push('focus indicator could not be determined');
  if (stop.obscured) issues.push('hidden behind other content when focused');
  issues.push(...(stop.flags || []));
  return { text: `${stop.el} (${stop.role}) - ${stop.label || 'no label'}`, issues: issues.join('; ') };
}

function buildFocusLog(page) {
  const kb = page.keyboardResults;
  const wrap = document.createElement('div');
  wrap.className = 'focus-log';

  const title = document.createElement('p');
  title.className = 'focus-title';
  title.textContent = `Focus order (${plural(kb.totalStops, 'stop', 'stops')})`;
  wrap.appendChild(title);

  const facts = document.createElement('ul');
  facts.className = 'focus-facts';
  const addFact = (text, bad) => {
    const li = document.createElement('li');
    li.textContent = text;
    if (bad) li.className = 'bad';
    facts.appendChild(li);
  };
  addFact(kb.skipLink.present ? `Skip link: "${kb.skipLink.text}"` : 'Skip link: none found', !kb.skipLink.present);
  addFact(`Keyboard traps: ${kb.traps.length}`, kb.traps.length > 0);
  addFact(`Not reachable by Tab: ${kb.unreachableCount}`, kb.unreachableCount > 0);
  for (const u of kb.unreachable.slice(0, 10)) addFact(`  ${u.el} - ${u.label || u.sel}: ${u.reason}`, true);
  if (kb.viewportHidden) addFact('The page was not visible during the scan, so Focus Not Obscured (2.4.11) was not checked. Re-scan with the tab in view.', true);
  if (kb.truncated) addFact(`Only the first ${kb.stops.length} stops were tested.`, false);
  if (kb.cssIncomplete) addFact('A stylesheet could not be read, so undetected focus indicators are reported as "could not be determined".', false);
  wrap.appendChild(facts);

  const list = document.createElement('ol');
  list.className = 'focus-list';
  list.tabIndex = 0;
  list.setAttribute('aria-label', `Focus order for ${page.name}`);
  for (const stop of kb.stops) {
    const li = document.createElement('li');
    const line = stopLine(stop);
    li.textContent = line.text;
    if (line.issues) {
      const flag = document.createElement('span');
      flag.className = 'stop-issue';
      flag.textContent = ` ⚠ ${line.issues}`;
      li.appendChild(flag);
    }
    list.appendChild(li);
  }
  wrap.appendChild(list);
  return wrap;
}

function buildRenameForm(page) {
  const form = document.createElement('form');
  form.className = 'rename-form';
  const input = document.createElement('input');
  input.type = 'text';
  input.value = page.name;
  input.setAttribute('aria-label', `New name for ${page.name}`);
  const save = document.createElement('button');
  save.type = 'submit';
  save.className = 'btn btn-small';
  save.textContent = 'Save';
  const cancel = document.createElement('button');
  cancel.type = 'button';
  cancel.className = 'btn btn-small';
  cancel.textContent = 'Cancel';
  const stop = () => {
    renamingId = null;
    render();
  };
  form.addEventListener('submit', (e) => {
    e.preventDefault();
    const name = input.value.trim();
    renamingId = null;
    if (name && name !== page.name) {
      page.name = name;
      saveAndRender();
    } else render();
  });
  cancel.addEventListener('click', stop);
  input.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') stop();
  });
  form.append(input, save, cancel);
  requestAnimationFrame(() => {
    input.focus();
    input.select();
  });
  return form;
}

function renderPageList() {
  const listScroll = el.pageList.scrollTop;
  const count = session.pages.length;
  el.sessionTitle.textContent = count ? `Session active · ${plural(count, 'page', 'pages')} scanned` : 'No session yet';
  el.pageList.innerHTML = '';
  el.emptyState.style.display = count === 0 ? 'flex' : 'none';
  const open = new Set(session.openDetails || []);

  for (const page of session.pages) {
    const node = el.pageRowTemplate.content.cloneNode(true);
    const li = node.querySelector('.page-row');
    li.dataset.pageId = page.pageId;

    const nameEl = node.querySelector('.page-name');
    if (renamingId === page.pageId) nameEl.replaceWith(buildRenameForm(page));
    else nameEl.textContent = page.name;

    if (failedEngines(page).length) node.querySelector('.page-check').textContent = '⚠';
    const countEl = node.querySelector('.page-count');
    countEl.textContent = plural(page.violationCount, 'violation', 'violations');
    countEl.classList.toggle('has-violations', page.violationCount > 0);
    node.querySelector('[data-action="delete"]').setAttribute('aria-label', `Remove ${page.name} from the session`);

    const details = node.querySelector('.page-details');
    details.open = open.has(page.pageId) || renamingId === page.pageId;
    details.addEventListener('toggle', () => {
      const set = new Set(session.openDetails || []);
      if (details.open) set.add(page.pageId);
      else set.delete(page.pageId);
      session.openDetails = [...set];
      persist({ touch: false });
    });
    details.querySelector('summary').setAttribute('aria-label', `Details for ${page.name}`);
    const urlEl = li.querySelector('.page-url');
    urlEl.textContent = page.url || '';
    urlEl.title = page.url || '';
    node.querySelector('.page-scanned').textContent = page.scannedAt ? `Scanned ${formatTimestamp(page.scannedAt)}` : '';

    const badgesEl = node.querySelector('.page-badges');
    for (const badge of pageBadges(page)) {
      const span = document.createElement('span');
      span.className = `badge badge-${badge.cls}`;
      span.textContent = badge.text;
      badgesEl.appendChild(span);
    }
    for (const btn of node.querySelectorAll('.page-row-actions [data-action]')) {
      btn.setAttribute('aria-label', `${btn.textContent} ${page.name}`);
    }
    if (hasKeyboardScan(page)) details.appendChild(buildFocusLog(page));
    el.pageList.appendChild(node);
  }
  el.pageList.scrollTop = listScroll;
}

// --- summary ---

const BUCKET_CLASS = {
  [conformance.BUCKETS.SUPPORTS]: 'supports',
  [conformance.BUCKETS.PARTIALLY]: 'partially',
  [conformance.BUCKETS.DOES_NOT]: 'does-not',
  [conformance.BUCKETS.NOT_APPLICABLE]: 'na',
  [conformance.BUCKETS.NOT_EVALUATED]: 'ne',
};

function renderSummary() {
  const results = conformance.computeAllConformance(session, WCAG22_ALL);
  const counts = conformance.summarizeBuckets(results);

  el.summary.supports.textContent = String(counts[conformance.BUCKETS.SUPPORTS]);
  el.summary.partially.textContent = String(counts[conformance.BUCKETS.PARTIALLY]);
  el.summary.doesNot.textContent = String(counts[conformance.BUCKETS.DOES_NOT]);
  el.summary.na.textContent = String(counts[conformance.BUCKETS.NOT_APPLICABLE]);
  el.summary.ne.textContent = String(counts[conformance.BUCKETS.NOT_EVALUATED]);

  el.criteriaList.innerHTML = '';
  for (const r of results) {
    const li = document.createElement('li');
    const name = document.createElement('span');
    name.className = 'criterion-name';
    name.textContent = `${r.sc} ${r.name}`;
    const bucket = document.createElement('span');
    bucket.className = `criterion-bucket bucket-text-${BUCKET_CLASS[r.bucket]}`;
    bucket.textContent = r.bucket;
    const select = document.createElement('select');
    select.className = 'criterion-override';
    select.setAttribute('aria-label', `Override for ${r.sc} ${r.name}`);
    for (const [value, text] of [['', 'Auto'], ['na', 'Not Applicable'], ['dns', 'Does Not Support']]) {
      const option = document.createElement('option');
      option.value = value;
      option.textContent = text;
      select.appendChild(option);
    }
    select.value = session.notApplicable.includes(r.sc) ? 'na' : session.doesNotSupport[r.sc] ? 'dns' : '';
    select.addEventListener('change', () => setOverride(r, select.value));
    li.append(name, bucket, select);
    if (r.overrideNote) {
      const note = document.createElement('span');
      note.className = 'criterion-note';
      note.textContent = `Note: ${r.overrideNote}`;
      li.appendChild(note);
    }
    el.criteriaList.appendChild(li);
  }
}

// Consultant override for one criterion: '' (automatic), 'na', or 'dns'. Does Not
// Support is only accepted with a note, which is printed in the report's remarks.
async function setOverride(criterion, value) {
  let note = '';
  if (value === 'dns') {
    const answer = await showDialog({
      message: `Rate ${criterion.sc} ${criterion.name} as Does Not Support? A note explaining the determination is required and will appear in the report.`,
      input: { label: 'Note', value: session.doesNotSupport[criterion.sc] || '' },
      buttons: [{ label: 'Save', value: true, primary: true }, { label: 'Cancel', value: null }],
    });
    note = answer ? answer.text : '';
    if (!note) {
      render();
      return;
    }
  }
  session.notApplicable = session.notApplicable.filter((sc) => sc !== criterion.sc);
  delete session.doesNotSupport[criterion.sc];
  if (value === 'na') session.notApplicable.push(criterion.sc);
  if (value === 'dns') session.doesNotSupport[criterion.sc] = note;
  saveAndRender();
}

// The product name goes on the report cover, so scanning and generating stay disabled
// until it is filled in.
function updateGating() {
  const hasProductName = session.productName.trim().length > 0;
  el.scanBtn.disabled = busy || !hasProductName || !(el.modeAxe.checked || el.modeKeyboard.checked);
  el.emptyScanBtn.disabled = el.scanBtn.disabled;
  el.scanHint.hidden = hasProductName;
  for (const btn of el.pageList.querySelectorAll('[data-action^="rescan"]')) btn.disabled = busy || !hasProductName;
  // With no pages the empty state carries the scan button.
  el.scanBtn.hidden = session.pages.length === 0;
  // Generate VPAT needs at least one scanned page.
  el.exportBtn.disabled = busy || !(hasProductName && conformance.getScannedPages(session).length > 0);
  el.newSessionBtn.disabled = busy;
}

// Local date as yyyy-mm-dd, the format <input type="date"> uses.
function todayIso() {
  const now = new Date();
  return new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString().slice(0, 10);
}

function render() {
  el.productName.value = session.productName;
  el.productVersion.value = session.productVersion;
  for (const key of TEXT_SETTINGS) el[key].value = session[key] || '';
  el.preparedBy.value = session.preparedBy || '';
  el.company.value = session.company || '';
  // The date follows today until the user picks one.
  el.reportDate.value = session.reportDate || todayIso();
  renderLastSaved();
  renderPageList();
  renderSummary();
  updateGating();
}

function saveAndRender() {
  persist();
  render();
}

// --- product fields ---

el.productName.addEventListener('input', () => {
  session.productName = el.productName.value.trim();
  updateGating();
});

el.productName.addEventListener('change', () => {
  session.productName = el.productName.value.trim();
  saveAndRender();
});

el.productVersion.addEventListener('change', () => {
  session.productVersion = el.productVersion.value.trim();
  saveAndRender();
});

// Free-text report settings that are simply stored and printed on the cover.
for (const key of TEXT_SETTINGS) {
  el[key].addEventListener('change', () => {
    session[key] = el[key].value.trim();
    saveAndRender();
  });
}

el.preparedBy.addEventListener('change', () => {
  session.preparedBy = el.preparedBy.value.trim();
  // Remembered beyond this session so the next one starts with it filled in.
  storage.rememberPreparedBy(session.preparedBy);
  saveAndRender();
});

el.company.addEventListener('change', () => {
  session.company = el.company.value.trim();
  saveAndRender();
});

el.reportDate.addEventListener('change', () => {
  session.reportDate = el.reportDate.value === todayIso() ? '' : el.reportDate.value;
  saveAndRender();
});

// Report settings start open; once collapsed they stay collapsed.
el.settings.open = session.settingsOpen !== false;
el.settings.addEventListener('toggle', () => {
  if (session.settingsOpen === el.settings.open) return;
  session.settingsOpen = el.settings.open;
  if (hasPersisted) persist({ touch: false });
});

el.modeAxe.addEventListener('change', updateGating);
el.modeKeyboard.addEventListener('change', updateGating);

// --- clear session ---

function startFreshSession() {
  storage.clearSession();
  session = storage.createEmptySession();
  hasPersisted = false;
  saveFailed = false;
  saveNote = '';
  renamingId = null;
  el.scanStatus.textContent = '';
  el.exportStatus.textContent = '';
  el.settings.open = true;
  render();
  window.scrollTo(0, 0);
  showSessionStatus('Session cleared — ready to scan');
}

let sessionStatusTimer = null;
function showSessionStatus(message) {
  clearTimeout(sessionStatusTimer);
  el.sessionStatus.textContent = message;
  sessionStatusTimer = setTimeout(() => {
    el.sessionStatus.textContent = '';
  }, 2000);
}

el.newSessionBtn.addEventListener('click', startFreshSession);

// --- scanning ---

function firstResult(injectionResults, what) {
  const entry = injectionResults && injectionResults[0];
  if (!entry || !entry.result) {
    const reason = entry && entry.error && entry.error.message;
    throw new Error(reason || `${what} returned no result.`);
  }
  return entry.result;
}

async function runEngineScan(tabId) {
  await browser.scripting.executeScript({ target: { tabId }, files: ENGINE_FILES });
  // axe-core also needs to be present in every frame to test iframe content; frames the
  // extension cannot access are skipped by the browser.
  try {
    await browser.scripting.executeScript({ target: { tabId, allFrames: true }, files: [ENGINE_FILES[0]] });
  } catch (err) {
    // Top frame already has it.
  }
  const raw = firstResult(
    await browser.scripting.executeScript({
      target: { tabId },
      func: engineScanInPage,
      args: [{ axeTags: AXE_RUN_ONLY_TAGS, versions: ENGINE_VERSIONS }],
    }),
    'Engine scan'
  );
  if (RULE_ENGINES.every((engine) => raw.errors[engine])) {
    throw new Error(Object.values(raw.errors)[0]);
  }
  const packed = packEngineScan(raw);
  packed.engines.ranAt = storage.nowIso();
  return packed;
}

// Stylesheets served from another origin can't be read by the page, so the scan can't
// see their :focus rules. The panel can fetch them with the extension's host access.
async function fetchStylesheet(href) {
  try {
    const res = await fetch(href, { credentials: 'omit', signal: AbortSignal.timeout(8000) });
    if (!res.ok) return { href, text: null };
    const text = await res.text();
    return { href, text: text.length > MAX_SHEET_CHARS ? null : text };
  } catch (err) {
    return { href, text: null };
  }
}

async function runKeyboardScan(tabId) {
  const blocked = (await browser.scripting.executeScript({ target: { tabId }, func: collectBlockedStylesheetsInPage }))[0];
  const hrefs = ((blocked && blocked.result) || []).slice(0, MAX_FETCHED_SHEETS);
  const fetchedSheets = await Promise.all(hrefs.map(fetchStylesheet));
  const raw = firstResult(
    await browser.scripting.executeScript({
      target: { tabId },
      func: keyboardScanInPage,
      args: [{ fetchedSheets, maxStops: MAX_FOCUS_STOPS }],
    }),
    'Keyboard scan'
  );
  return { ranAt: storage.nowIso(), ...raw };
}

// Screenshot of the visible part of the tab, scaled down so a session of many pages
// still fits in localStorage. Returns null when the browser refuses the capture.
async function captureScreenshot(tab) {
  try {
    const source = await browser.tabs.captureVisibleTab(tab.windowId, { format: 'jpeg', quality: 80 });
    const img = new Image();
    await new Promise((resolve, reject) => {
      img.onload = resolve;
      img.onerror = reject;
      img.src = source;
    });
    const scale = Math.min(1, SCREENSHOT_MAX_WIDTH / img.naturalWidth);
    const canvas = document.createElement('canvas');
    canvas.width = Math.round(img.naturalWidth * scale);
    canvas.height = Math.round(img.naturalHeight * scale);
    canvas.getContext('2d').drawImage(img, 0, 0, canvas.width, canvas.height);
    return { dataUrl: canvas.toDataURL('image/jpeg', 0.6), width: canvas.width, height: canvas.height };
  } catch (err) {
    return null;
  }
}

// Browser and operating system the scan ran in, for the report's scope section.
function detectEnvironment() {
  const ua = navigator.userAgent;
  const pick = (re) => (re.exec(ua) || [])[1];
  let browserName = 'Unknown browser';
  if (pick(/Edg\/(\d+)/)) browserName = `Microsoft Edge ${pick(/Edg\/(\d+)/)}`;
  else if (pick(/Firefox\/(\d+)/)) browserName = `Firefox ${pick(/Firefox\/(\d+)/)}`;
  else if (pick(/Chrome\/(\d+)/)) browserName = `Chrome ${pick(/Chrome\/(\d+)/)}`;
  else if (pick(/Version\/(\d+).*Safari/)) browserName = `Safari ${pick(/Version\/(\d+).*Safari/)}`;
  let os = 'unknown operating system';
  if (/Windows/.test(ua)) os = 'Windows';
  else if (/CrOS/.test(ua)) os = 'ChromeOS';
  else if (/Mac OS X/.test(ua)) os = 'macOS';
  else if (/Android/.test(ua)) os = 'Android';
  else if (/Linux/.test(ua)) os = 'Linux';
  return `${browserName} on ${os}`;
}

const sameDocument = (a, b) => (a || '').split('#')[0] === (b || '').split('#')[0];

function applyEngineScan(page, packed) {
  page.engines = packed.engines;
  page.axeResults = packed.axeResults;
  page.ibmResults = packed.ibmResults;
  page.codesnifferResults = packed.codesnifferResults;
}

function clearScans(page, which) {
  if (which.engines) applyEngineScan(page, { engines: null, axeResults: [], ibmResults: [], codesnifferResults: [] });
  if (which.keyboard) page.keyboardResults = {};
}

// Decides which session entry a new scan goes into: asks for the page name, and if the
// URL is already in the session, whether to replace that scan or keep both.
// Returns { page, isNew } or null if the user cancelled.
async function chooseTargetPage(tab) {
  const named = await showDialog({
    message: 'Name this page for the report.',
    input: { label: 'Page name', value: tab.title || '' },
    buttons: [{ label: 'Scan', value: true, primary: true }, { label: 'Cancel', value: null }],
  });
  if (!named) return null;
  const name = named.text || tab.title || 'Untitled page';

  const existing = session.pages.find((p) => p.url && tab.url && sameDocument(p.url, tab.url));
  if (existing) {
    const choice = await showDialog({
      message: `This URL is already in the session as "${existing.name}" (scanned ${formatTimestamp(existing.scannedAt)}). ` +
        'Replace the previous scan, or keep both?',
      buttons: [
        { label: 'Replace previous scan', value: 'replace', primary: true },
        { label: 'Keep both', value: 'both' },
        { label: 'Cancel', value: null },
      ],
    });
    if (!choice) return null;
    if (choice.value === 'replace') return { page: existing, isNew: false, replace: true, name };
  }
  return { page: storage.createPage(name, tab.url), isNew: true };
}

// modes: { axe: boolean, keyboard: boolean }. With existingPageId the active tab is
// re-scanned into that entry; otherwise the scan is added to the session as a page.
async function handleScan(modes, existingPageId) {
  if (busy) return;
  // Firefox treats MV3 host permissions as optional; this must run inside the click.
  let granted = true;
  try {
    granted = await browser.permissions.request({ origins: HOST_ORIGINS });
  } catch (err) {
    granted = true;
  }
  if (!granted) {
    el.scanStatus.textContent = 'Scan cancelled: the extension needs access to the page to scan it.';
    return;
  }

  busy = true;
  render();
  const done = [];
  const failed = [];
  try {
    const tab = await getActiveTab();
    if (!tab || !tab.id) throw new Error('No active tab available to scan.');

    let target;
    if (existingPageId) {
      const page = session.pages.find((p) => p.pageId === existingPageId);
      if (!page) throw new Error('Page not found.');
      if (page.url && tab.url && !sameDocument(page.url, tab.url)) {
        const ok = await confirmAction(
          `"${page.name}" was scanned at ${page.url}. The active tab is ${tab.url}. Replace its results with a scan of the active tab?`,
          'Re-scan with active tab'
        );
        if (!ok) {
          el.scanStatus.textContent = 'Re-scan cancelled.';
          return;
        }
      }
      target = { page, isNew: false };
    } else {
      target = await chooseTargetPage(tab);
      if (!target) {
        el.scanStatus.textContent = 'Scan cancelled.';
        return;
      }
    }
    const { page } = target;

    // Taken first, before the keyboard scan moves focus and scroll position.
    const screenshot = await captureScreenshot(tab);

    const results = {};
    if (modes.axe) {
      el.scanStatus.textContent = 'Running Engine Scan (axe-core, IBM Equal Access, HTML CodeSniffer)...';
      try {
        results.engines = await runEngineScan(tab.id);
        const errors = results.engines.engines.errors;
        const ran = RULE_ENGINES.filter((e) => !errors[e]).map((e) => `${e} ${results.engines.engines.versions[e]}`);
        done.push(`Engine Scan complete (${ran.join(', ')})`);
        for (const engine of Object.keys(errors)) failed.push(`${engine} failed: ${errors[engine]}`);
      } catch (err) {
        console.error('Engine scan failed', err);
        failed.push(`Engine Scan failed: ${err && err.message ? err.message : String(err)}`);
      }
    }
    if (modes.keyboard) {
      el.scanStatus.textContent = 'Running Keyboard Scan...';
      try {
        results.keyboard = await runKeyboardScan(tab.id);
        done.push(`Keyboard Scan complete (${plural(results.keyboard.totalStops, 'focus stop', 'focus stops')})`);
      } catch (err) {
        console.error('Keyboard scan failed', err);
        failed.push(`Keyboard Scan failed: ${err && err.message ? err.message : String(err)}`);
      }
    }

    if (results.engines || results.keyboard) {
      const scannedUrl = (results.engines && results.engines.url) || (results.keyboard && results.keyboard.url) || tab.url || '';
      // Results from two different URLs, or from before a "replace", must not be mixed
      // under one entry.
      if (target.replace || !sameDocument(page.url, scannedUrl)) clearScans(page, { engines: true, keyboard: true });
      page.url = scannedUrl;
      if (target.name) page.name = target.name;
      if (results.engines) applyEngineScan(page, results.engines);
      if (results.keyboard) page.keyboardResults = results.keyboard;
      if (screenshot) page.screenshot = screenshot;
      page.scannedAt = storage.nowIso();
      page.environment = detectEnvironment();
      page.violationCount = countViolations(page);
      if (target.isNew) session.pages.push(page);
      done.push(`"${page.name}": ${plural(page.violationCount, 'violation', 'violations')}`);
      persist();
    }
  } catch (err) {
    console.error('Scan failed', err);
    failed.push(`Scan failed: ${err && err.message ? err.message : String(err)}`);
  } finally {
    busy = false;
    render();
  }
  if (done.length || failed.length) el.scanStatus.textContent = [...done, ...failed].join(' | ');
}

const scanCurrentPage = () => handleScan({ axe: el.modeAxe.checked, keyboard: el.modeKeyboard.checked });
el.scanBtn.addEventListener('click', scanCurrentPage);
el.emptyScanBtn.addEventListener('click', scanCurrentPage);

// --- page list actions (remove / rename / re-scan) ---

el.pageList.addEventListener('click', async (e) => {
  const actionBtn = e.target.closest('[data-action]');
  if (!actionBtn) return;
  const li = e.target.closest('.page-row');
  const pageId = li && li.dataset.pageId;
  const page = session.pages.find((p) => p.pageId === pageId);
  if (!page) return;

  const action = actionBtn.dataset.action;
  if (action === 'delete') {
    const ok = await confirmAction(`Remove "${page.name}" and its scan results from the session?`, 'Remove page', true);
    if (!ok) return;
    session.pages = session.pages.filter((p) => p.pageId !== pageId);
    session.openDetails = (session.openDetails || []).filter((id) => id !== pageId);
    saveAndRender();
  } else if (action === 'rename') {
    renamingId = pageId;
    render();
  } else if (action === 'rescan-axe') {
    handleScan({ axe: true }, pageId);
  } else if (action === 'rescan-keyboard') {
    handleScan({ keyboard: true }, pageId);
  }
});

// --- generate VPAT ---

el.exportBtn.addEventListener('click', async () => {
  el.exportBtn.disabled = true;
  el.exportStatus.textContent = 'Building report...';
  try {
    const results = conformance.computeAllConformance(session, WCAG22_ALL);
    const resultsWithRemarks = results.map((r) => ({ ...r, remarks: buildRemarks(r) }));
    const model = buildDocModel(session, resultsWithRemarks);

    await exportDocx(model);
    await exportPdf(model);

    el.exportStatus.textContent = `VPAT generated from ${plural(model.pages.length, 'page', 'pages')} (.docx and .pdf) - check your downloads.`;
  } catch (err) {
    console.error('Export failed', err);
    el.exportStatus.textContent = `VPAT generation failed: ${err && err.message ? err.message : String(err)}`;
  } finally {
    updateGating();
  }
});

// --- scroll position persistence ---

let scrollSaveTimer = null;
const saveScroll = () => {
  clearTimeout(scrollSaveTimer);
  scrollSaveTimer = setTimeout(() => {
    session.scrollPosition = window.scrollY;
    session.listScrollPosition = el.pageList.scrollTop;
    // Scrolling is not a change to the session, so it must not reset the 7-day clock.
    if (hasPersisted) persist({ touch: false });
  }, 300);
};
window.addEventListener('scroll', saveScroll);
el.pageList.addEventListener('scroll', saveScroll);

// --- init ---

// A session untouched for 7 days is offered back rather than silently resumed.
async function checkStaleSession() {
  if (!storage.isStale(session)) return;
  const date = new Date(session.updatedAt).toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' });
  const choice = await showDialog({
    message: `Resume session from ${date}? It contains ${plural(session.pages.length, 'page', 'pages')}.`,
    buttons: [{ label: 'Resume', value: 'resume', primary: true }, { label: 'Start new session', value: 'fresh', danger: true }],
  });
  if (choice && choice.value === 'fresh') startFreshSession();
  // Resuming (or dismissing) counts as picking the session back up.
  else persist();
}

// Opening the panel on a different site than the last scan offers a fresh session, so
// results from one site don't end up in another site's report. "Keep" is remembered for
// that site so the question isn't asked again on every open.
async function checkDomainChange() {
  await refreshActiveTab();
  if (busy || session.pages.length === 0) return;
  const previous = storage.lastScannedDomain(session);
  const current = storage.domainOf(activeTab && activeTab.url);
  if (!previous || !current || previous === current) return;
  if ((session.keptForDomains || []).includes(current)) return;
  const choice = await showDialog({
    message: `You have scan data from ${previous}. Clear it and start fresh?`,
    // Keeping the data is the prominent (and Enter) choice; clearing is the outline button.
    buttons: [{ label: 'Keep', value: 'keep', primary: true }, { label: 'Clear', value: 'clear', danger: true }],
  });
  if (choice && choice.value === 'clear') {
    startFreshSession();
  } else {
    session.keptForDomains = [...(session.keptForDomains || []), current];
    persist({ touch: false });
  }
}

async function startupChecks() {
  await checkStaleSession();
  await checkDomainChange();
}

el.versionBadge.textContent = `v${APP_VERSION}`;
render();
requestAnimationFrame(() => {
  window.scrollTo(0, session.scrollPosition || 0);
  el.pageList.scrollTop = session.listScrollPosition || 0;
});
startupChecks();

// Keep "Current page" in step with the tab the user is looking at.
if (browser.tabs.onActivated) browser.tabs.onActivated.addListener(refreshActiveTab);
if (browser.tabs.onUpdated) {
  browser.tabs.onUpdated.addListener((tabId, changeInfo) => {
    if (changeInfo.url || changeInfo.status === 'complete') refreshActiveTab();
  });
}
if (browser.windows && browser.windows.onFocusChanged) browser.windows.onFocusChanged.addListener(refreshActiveTab);
