const {
  Document,
  Packer,
  Paragraph,
  TextRun,
  HeadingLevel,
  Table,
  TableRow,
  TableCell,
  WidthType,
  ShadingType,
  PageBreak,
  ImageRun,
  BorderStyle,
  AlignmentType,
  Footer,
  ExternalHyperlink,
} = require('docx');
const { buildFileName, downloadBlob } = require('./downloadUtil');
const { THEME, LEVEL_TINT } = require('./reportTheme');

// US Letter with 1" margins: 9360 twips of usable width. Word needs absolute column
// widths (percentages alone collapse in some viewers).
const CONTENT_WIDTH = 9360;
const MONO = 'Consolas';

const shade = (fill) => ({ type: ShadingType.CLEAR, color: 'auto', fill });
const line = (color, size) => ({ style: BorderStyle.SINGLE, size: size || 4, color });
const GRID = {
  top: line(THEME.border), bottom: line(THEME.border), left: line(THEME.border), right: line(THEME.border),
  insideHorizontal: line(THEME.border), insideVertical: line(THEME.border),
};

// Placeholders are highlighted so an unfilled field is obvious before the report is sent.
function placeholderRun(text) {
  return new TextRun({ text, bold: true, shading: shade(THEME.placeholder) });
}

function para(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 100 },
    alignment: opts.alignment,
    children: [new TextRun({ text, bold: !!opts.bold, italics: !!opts.italics, color: opts.color, size: opts.size })],
  });
}

// "Label: value" with a bold label; value may run over several lines.
function labeledParagraph(label, value, isPlaceholder) {
  return new Paragraph({
    spacing: { after: 120 },
    children: [
      new TextRun({ text: `${label}: `, bold: true }),
      isPlaceholder ? placeholderRun(value) : new TextRun({ text: value }),
    ],
  });
}

function heading(text, level) {
  const sub = level === HeadingLevel.HEADING_2;
  return new Paragraph({
    heading: level || HeadingLevel.HEADING_1,
    keepNext: true,
    spacing: { before: sub ? 280 : 400, after: 140 },
    children: [new TextRun({ text, bold: true, color: sub ? THEME.navy : THEME.purple, size: sub ? 24 : 30 })],
  });
}

// Cell content: a string, or { text, link?, fill?, placeholder? }. Line breaks start new
// paragraphs, which is how remarks bullets are laid out.
function cell(content, width, opts = {}) {
  const c = typeof content === 'object' && content !== null ? content : { text: content };
  const run = (text) => new TextRun({
    text,
    bold: !!opts.bold,
    color: opts.color,
    font: opts.mono ? MONO : undefined,
    size: opts.size,
    style: c.link ? 'Hyperlink' : undefined,
  });
  const children = String(c.text).split('\n').map((text) => new Paragraph({
    spacing: { after: 40 },
    children: [c.placeholder ? placeholderRun(text) : c.link ? new ExternalHyperlink({ link: c.link, children: [run(text)] }) : run(text)],
  }));
  return new TableCell({
    width: { size: width, type: WidthType.DXA },
    shading: shade(c.fill || opts.fill || THEME.white),
    margins: { top: 80, bottom: 60, left: 110, right: 110 },
    children,
  });
}

// head: column titles on a navy header row; widths: percentages. Body rows alternate
// between white and light grey.
function table(head, widths, rows, opts = {}) {
  const dxa = widths.map((pct) => Math.round((CONTENT_WIDTH * pct) / 100));
  const headerRow = new TableRow({
    tableHeader: true,
    cantSplit: true,
    children: head.map((h, i) => cell(h, dxa[i], { bold: true, fill: THEME.navy, color: THEME.white })),
  });
  const body = rows.map(
    (row, r) =>
      new TableRow({
        cantSplit: true,
        children: row.map((c, i) => cell(c, dxa[i], { fill: opts.fill || (r % 2 === 0 ? THEME.white : THEME.rowAlt), mono: opts.mono, size: opts.size })),
      })
  );
  return new Table({ width: { size: CONTENT_WIDTH, type: WidthType.DXA }, columnWidths: dxa, borders: GRID, rows: [headerRow, ...body] });
}

function criteriaTable(rows) {
  return table(
    ['Criteria', 'Conformance Level', 'Remarks and Explanations'],
    [35, 20, 45],
    rows.map((r) => [
      { text: r.criteria, link: r.link },
      { text: r.conformance, fill: LEVEL_TINT[r.conformance] },
      r.remarks || '',
    ])
  );
}

function screenshot(shot) {
  const bytes = Uint8Array.from(atob(shot.dataUrl.split(',')[1]), (ch) => ch.charCodeAt(0));
  const width = Math.min(600, shot.width);
  return new Paragraph({
    spacing: { after: 120 },
    children: [new ImageRun({ type: 'jpg', data: bytes, transformation: { width, height: Math.round((shot.height * width) / shot.width) } })],
  });
}

function focusLog(entry) {
  const out = [para('Keyboard focus log', { bold: true }), ...entry.summary.map((text) => para(text))];
  if (entry.rows.length) {
    out.push(
      table(
        ['#', 'Element', 'Role', 'Label', 'Focus indicator', 'Notes'],
        [6, 14, 11, 27, 18, 24],
        entry.rows.map((r) => [r.order, r.element, r.role, r.label, r.indicator, r.notes]),
        { mono: true, fill: THEME.surface, size: 16 }
      )
    );
  }
  if (entry.traps.length) {
    out.push(para('Keyboard traps detected', { bold: true }));
    out.push(table(['Element', 'Detail'], [45, 55], entry.traps.map((t) => [t.element, t.detail])));
  }
  if (entry.unreachable.length) {
    out.push(para('Interactive elements not reachable by Tab', { bold: true }));
    out.push(table(['Element', 'Why it was flagged'], [45, 55], entry.unreachable.map((u) => [u.element, u.detail])));
    if (entry.unreachableOmitted) out.push(para(`${entry.unreachableOmitted} further element(s) not listed.`, { italics: true }));
  }
  return out;
}

function pageAppendix(entry) {
  const out = [
    heading(entry.name, HeadingLevel.HEADING_2),
    labeledParagraph('URL', entry.url),
    labeledParagraph('Scanned', entry.scannedAt),
  ];
  if (entry.screenshot) {
    out.push(para('Screenshot at the time of the scan', { bold: true }));
    out.push(screenshot(entry.screenshot));
  }
  out.push(para(`Violations (${entry.violations.length})`, { bold: true }));
  if (entry.violations.length) {
    out.push(
      table(
        ['Criterion', 'Element', 'Issue', 'Detected by'],
        [12, 36, 32, 20],
        entry.violations.map((v) => [v.criterion, v.element, v.description, v.engines])
      )
    );
  } else out.push(para('No violations detected on this page.'));
  if (entry.focus) out.push(...focusLog(entry.focus));
  return out;
}

function buildDocxDocument(model) {
  const { meta } = model;
  const pageBreak = () => new Paragraph({ children: [new PageBreak()] });

  const children = [
    // Cover: plain white page, purple type.
    new Paragraph({
      heading: HeadingLevel.TITLE,
      spacing: { before: 600, after: 80 },
      children: [new TextRun({ text: meta.title, bold: true, color: THEME.purple, size: 48 })],
    }),
    new Paragraph({
      spacing: { after: 500 },
      children: [new TextRun({ text: meta.subtitle, italics: true, color: THEME.purple, size: 26 })],
    }),
    ...model.coverFields.map((f) => labeledParagraph(f.label, f.value, f.placeholder)),
    pageBreak(),

    heading('Applicable Standards/Guidelines'),
    para('This report covers the degree of conformance for the following accessibility standards/guidelines:'),
    table(['Standard/Guideline', 'Included in Report'], [60, 40], model.standards),

    heading('Terms'),
    para('The terms used in the Conformance Level information are defined as follows:'),
    ...model.terms.map(([term, definition]) => new Paragraph({
      bullet: { level: 0 },
      spacing: { after: 80 },
      children: [new TextRun({ text: `${term}: `, bold: true }), new TextRun({ text: definition })],
    })),
    ...(model.termsNote ? [para(model.termsNote, { italics: true })] : []),
    pageBreak(),

    heading('WCAG 2.2 Report'),
    heading(model.tables[0].title, HeadingLevel.HEADING_2),
    criteriaTable(model.tables[0].rows),
    heading(model.tables[1].title, HeadingLevel.HEADING_2),
    criteriaTable(model.tables[1].rows),

    heading('Legal Disclaimer'),
    ...model.legalDisclaimer.map((text) => para(text)),
    para(model.trademarkNotice, { italics: true, color: THEME.muted }),
    pageBreak(),

    heading('Appendix A: Evaluation Details'),
    para('Pages tested', { bold: true }),
    table(
      ['Page', 'URL', 'Scanned', 'Violations'],
      [22, 43, 22, 13],
      model.pages.map((p) => [p.name, p.url, p.scannedAt, p.violationCount])
    ),
    para(''),
    ...model.scope.facts.map(([label, value]) => labeledParagraph(label, value)),
    para('Out of scope', { bold: true }),
    para(model.scope.outOfScope),
    para('Methodology', { bold: true }),
    ...model.evaluationMethods.map((text) => para(text)),
    table(
      ['Page', 'Rule engines', 'Keyboard scan'],
      [24, 46, 30],
      model.pages.map((p) => [p.name, p.auto, p.keyboard])
    ),
    para(''),
    para('Criteria by conformance level', { bold: true }),
    table(
      ['Conformance Level', 'Criteria'],
      [60, 40],
      model.summary.cards.map((card) => [{ text: card.label, fill: LEVEL_TINT[card.label] }, card.count])
    ),
  ];

  if (model.pageAppendix.length) {
    children.push(pageBreak());
    children.push(heading('Appendix B: Page Details'));
    children.push(para(
      'For each scanned page: every violation detected, and the sequential focus order recorded by the keyboard ' +
      'scan for consultant review of WCAG 2.4.3 Focus Order.'
    ));
    for (const entry of model.pageAppendix) children.push(...pageAppendix(entry));
  }

  const footer = new Footer({
    children: [new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [new TextRun({ text: `${meta.docTitle}  ·  ${meta.reportDate}`, size: 16, color: THEME.muted })],
    })],
  });

  return new Document({
    title: meta.docTitle,
    creator: meta.appName,
    styles: { default: { document: { run: { font: 'Arial', size: 20, color: THEME.text } } } },
    sections: [{ properties: {}, footers: { default: footer }, children }],
  });
}

async function exportDocx(model) {
  const doc = buildDocxDocument(model);
  const blob = await Packer.toBlob(doc);
  downloadBlob(blob, buildFileName(model, 'docx'));
}

module.exports = { buildDocxDocument, exportDocx };
