function slugify(str) {
  return (str || 'untitled')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/(^-|-$)/g, '') || 'untitled';
}

function buildFileName(model, ext) {
  const productSlug = slugify(model.meta.productName);
  const dateSlug = new Date().toISOString().slice(0, 10);
  return `${productSlug}-VPAT-${dateSlug}.${ext}`;
}

function downloadBlob(blob, filename) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
  setTimeout(() => URL.revokeObjectURL(url), 4000);
}

module.exports = { slugify, buildFileName, downloadBlob };
