const { summarizeBuckets, getScannedPages } = require('./conformance');
const { ENGINES, RULE_ENGINES, hasEngineScan, hasKeyboardScan, pageFindings } = require('./findings');
const { reportProductName } = require('./storage');

const APP_NAME = 'VPAT Generator';

function formatDate(date) {
  return date.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
}

function formatDateTime(iso) {
  return iso ? new Date(iso).toLocaleString('en-US', { dateStyle: 'medium', timeStyle: 'short' }) : '';
}

function uniqueSorted(list) {
  return [...new Set(list.filter(Boolean))].sort();
}

// Scans in one session can span several days; the report states the real range rather
// than the export date.
function scanDateRange(pages) {
  const times = [];
  for (const p of pages) {
    if (hasEngineScan(p) && p.engines.ranAt) times.push(new Date(p.engines.ranAt).getTime());
    if (hasKeyboardScan(p)) times.push(new Date(p.keyboardResults.ranAt).getTime());
  }
  if (times.length === 0) return formatDate(new Date());
  const first = formatDate(new Date(Math.min(...times)));
  const last = formatDate(new Date(Math.max(...times)));
  return first === last ? first : `${first} to ${last}`;
}

// Numeric order for criterion numbers ("1.4.3" before "1.4.10").
function compareCriteria(a, b) {
  const pa = a.split('.').map(Number);
  const pb = b.split('.').map(Number);
  for (let i = 0; i < 3; i += 1) if (pa[i] !== pb[i]) return pa[i] - pb[i];
  return 0;
}

// WCAG anchors are the criterion name in lower case, punctuation dropped, hyphenated.
function criterionLink(name) {
  const slug = name.toLowerCase().replace(/[^a-z0-9\s-]/g, '').trim().replace(/\s+/g, '-');
  return `https://www.w3.org/TR/WCAG22/#${slug}`;
}

const NUMBER_WORDS = ['zero', 'one', 'two', 'three', 'four'];

function joinWithAnd(list) {
  if (list.length <= 1) return list[0] || '';
  if (list.length === 2) return `${list[0]} and ${list[1]}`;
  return `${list.slice(0, -1).join(', ')}, and ${list[list.length - 1]}`;
}

function indicatorText(stop) {
  if (stop.ind === 'missing') return 'Not detected';
  if (stop.ind === 'unknown') return 'Could not be determined';
  return `Visible (${stop.kinds.join(', ')})`;
}

function stopNotes(stop) {
  const notes = [...(stop.flags || [])];
  if (stop.obscured) notes.push(`Hidden behind ${stop.obscured} when focused (2.4.11)`);
  if (stop.ind === 'unknown') notes.push('A stylesheet could not be read; check the indicator manually');
  if (stop.app === 'fail') notes.push('Indicator is thinner than 2px or under 3:1 contrast (2.4.13 Focus Appearance, Level AAA - advisory)');
  return notes.join('; ');
}

function buildFocusAppendix(page) {
  const kb = page.keyboardResults;
  const missing = kb.stops.filter((s) => s.ind === 'missing').length;
  const unknown = kb.stops.filter((s) => s.ind === 'unknown').length;
  const obscured = kb.stops.filter((s) => s.obscured).length;

  const summary = [
    `Scanned ${formatDateTime(kb.ranAt)}. ${kb.totalStops} focus stop(s) found${kb.truncated ? `; the first ${kb.stops.length} are listed` : ''}.`,
    kb.skipLink.present
      ? `Skip link: present ("${kb.skipLink.text}" to ${kb.skipLink.target}).`
      : 'Skip link: none found.',
    `Focus indicator not detected on ${missing} stop(s)${unknown ? `; ${unknown} could not be determined` : ''}. ` +
      `Focused element fully hidden behind other content on ${obscured} stop(s).`,
    `Keyboard traps detected: ${kb.traps.length}. Interactive elements not reachable by Tab: ${kb.unreachableCount}.`,
  ];
  if (kb.modalContainment) {
    summary.push(`${kb.modalContainment} focus loop(s) inside a modal dialog were treated as expected behavior; confirm the dialog can be closed from the keyboard.`);
  }

  return {
    name: page.name,
    url: kb.url || page.url || '',
    summary,
    rows: kb.stops.map((s) => ({
      order: String(s.i),
      element: s.el,
      role: s.role,
      label: s.label || '(no accessible label found)',
      indicator: indicatorText(s),
      notes: stopNotes(s),
    })),
    traps: kb.traps.map((t) => ({ element: `${t.el} - ${t.label || t.sel}`, detail: t.detail })),
    unreachable: kb.unreachable.map((u) => ({ element: `${u.el} - ${u.label || u.sel}`, detail: u.reason })),
    unreachableOmitted: Math.max(0, kb.unreachableCount - kb.unreachable.length),
  };
}

// Builds the single report model consumed identically by docxExport.js and pdfExport.js,
// so the .docx and .pdf outputs always describe the same findings.
function buildDocModel(session, conformanceResultsWithRemarks) {
  const scannedPages = getScannedPages(session);
  const enginePages = scannedPages.filter(hasEngineScan);
  const keyboardPages = scannedPages.filter(hasKeyboardScan);
  const scanDates = scanDateRange(scannedPages);

  // Version(s) of each rule engine that actually produced results in this session.
  const engineVersions = {};
  for (const engine of RULE_ENGINES) {
    const versions = uniqueSorted(enginePages.filter((p) => !(p.engines.errors || {})[engine]).map((p) => (p.engines.versions || {})[engine]));
    if (versions.length) engineVersions[engine] = versions.join(', ');
  }
  const layers = [
    ...Object.keys(engineVersions).map((engine) => `${engine} ${engineVersions[engine]}`),
    ...(keyboardPages.length ? ['programmatic keyboard simulation'] : []),
  ];
  const tools = joinWithAnd(layers);
  const axeVersion = engineVersions[ENGINES.AXE] || 'N/A';

  // The four-layer statement and its coverage figure only apply when all four layers
  // ran; otherwise the report names just the layers that were used.
  const layersStatement = layers.length === 4
    ? `Automated testing using four scanning layers: ${tools}. Automated testing covers approximately 50–55% of WCAG 2.2 Level A and AA success criteria. Coverage varies by page complexity.`
    : `Automated testing using ${layers.length === 1 ? 'one scanning layer' : `${NUMBER_WORDS[layers.length]} scanning layers`}: ${tools}.`;

  const scopeNote =
    `This report reflects automated testing conducted using ${tools} on ${scanDates}. ` +
    'The following criteria require additional manual evaluation and are marked Not Evaluated: screen reader ' +
    'compatibility (JAWS, NVDA), cognitive accessibility, focus order logical sequence, and all criteria ' +
    'outside automated detection scope. Manual testing results will be added separately.';

  const legalDisclaimer = [
    'This report reflects the state of the product at the time of testing. Results may change as the product is updated.',
    'The findings come from automated tools, which can detect only a subset of WCAG success criteria failures. A ' +
    'result of "Supports" means no failure was detected by the tools listed, not that conformance has been verified. ' +
    'Criteria outside automated scope are marked "Not Evaluated" and require review by a qualified accessibility professional.',
    'This document is a draft accessibility conformance report. It is not a legal certification of compliance with ' +
    'any law, regulation or standard.',
  ];

  const evaluationMethods = [
    layersStatement,
    `${scannedPages.length} page(s) were tested, ${scanDates}.`,
  ];
  if (enginePages.length) {
    evaluationMethods.push(
      `Rule engines (${enginePages.length} page(s)): each engine is run against the live page and its failures are mapped to ` +
      'WCAG success criteria using the engine\'s own mapping (axe-core rule tags, the IBM Equal Access WCAG 2.2 policy, ' +
      'and HTML CodeSniffer WCAG 2.1 AA message codes). Only definite failures are counted; items an engine flags ' +
      'as needing review are reported separately. When more than one engine reports the same element against the ' +
      'same criterion, it is counted once.'
    );
  }
  if (keyboardPages.length) {
    evaluationMethods.push(
      `Keyboard scan (${keyboardPages.length} page(s)): the sequential focus order is computed from the page, focus is moved ` +
      'to each stop in turn, and Tab and Shift+Tab key events are dispatched at each stop. The scan records each ' +
      'stop\'s element type, role and label, compares styles with and without focus to detect a visible focus ' +
      'indicator, checks whether the focused element is hidden behind fixed or sticky content, looks for key ' +
      'handlers that keep focus from leaving a component, lists interactive elements that are not Tab stops, and ' +
      'checks for a skip link. Browsers do not act on scripted key presses, so this is a simulation and does not ' +
      'replace testing with a physical keyboard.'
    );
  }
  evaluationMethods.push(
    'Conformance levels are assigned per criterion from the number of violation instances found across the pages ' +
    'where a scan covering that criterion ran. An instance is one failing element, counted once however many ' +
    'engines reported it: no instances = Supports; 1 to 4 = Partially Supports; 5 or more = Does Not ' +
    'Support; any failure of 2.4.1 Bypass Blocks = Does Not Support. Criteria with no automated check are marked Not Evaluated. Not ' +
    'Applicable is assigned only where the consultant explicitly determined the criterion does not apply. A ' +
    'consultant may also rate a criterion Does Not Support directly; those rows begin "Consultant determination".'
  );

  const rows = conformanceResultsWithRemarks.map((r) => ({
    sc: r.sc,
    name: r.name,
    level: r.level,
    conformance: r.bucket,
    remarks: r.remarks,
  }));

  const tables = [
    { title: 'Table 1: Success Criteria, Level A', rows: rows.filter((r) => r.level === 'A') },
    { title: 'Table 2: Success Criteria, Level AA', rows: rows.filter((r) => r.level === 'AA') },
  ];

  const summary = {
    totalPagesScanned: scannedPages.length,
    bucketCounts: summarizeBuckets(conformanceResultsWithRemarks),
  };

  const pages = scannedPages.map((p) => ({
    name: p.name,
    url: p.url || '',
    scannedAt: formatDateTime(p.scannedAt),
    violationCount: String(pageFindings(p).length),
    auto: hasEngineScan(p)
      ? `${RULE_ENGINES.map((e) => ((p.engines.errors || {})[e] ? `${e} failed` : `${e} ${(p.engines.versions || {})[e] || ''}`.trim())).join(', ')}; ` +
        formatDateTime(p.engines.ranAt)
      : 'Not run',
    keyboard: hasKeyboardScan(p)
      ? `${formatDateTime(p.keyboardResults.ranAt)}: ${p.keyboardResults.totalStops} focus stop(s)`
      : 'Not run',
  }));

  // One appendix section per page: details, screenshot, every violation, focus order.
  const pageAppendix = scannedPages.map((p) => ({
    name: p.name,
    url: p.url || '',
    scannedAt: formatDateTime(p.scannedAt),
    screenshot: p.screenshot || null,
    violations: pageFindings(p)
      .slice()
      .sort((a, b) => compareCriteria(a.wcagCriterion, b.wcagCriterion))
      .map((r) => ({
        criterion: `${r.wcagCriterion} (${r.level})`,
        element: r.snippet && r.snippet !== r.element ? `${r.snippet}\n${r.element}` : r.element,
        description: r.description,
        engines: r.engineSource.join(', '),
      })),
    focus: hasKeyboardScan(p) ? buildFocusAppendix(p) : null,
  }));

  const counts = summarizeBuckets(conformanceResultsWithRemarks);
  const summaryCards = ['Supports', 'Partially Supports', 'Does Not Support', 'Not Evaluated']
    .map((label) => ({ label, count: String(counts[label]) }));
  // Not Applicable only appears once the consultant has used it.
  if (counts['Not Applicable']) summaryCards.push({ label: 'Not Applicable', count: String(counts['Not Applicable']) });

  const preparedBy = (session.preparedBy || '').trim();
  const company = (session.company || '').trim();
  const reportDay = session.reportDate ? new Date(`${session.reportDate}T12:00:00`) : new Date();
  // Report settings entry first, then the scanned site's domain, never a page title.
  const productName = reportProductName(session) || '(Product name not set)';
  const layerNames = [...Object.keys(engineVersions), ...(keyboardPages.length ? ['Keyboard simulation'] : [])];
  const description = (session.productDescription || '').trim();
  const contact = (session.contactInfo || '').trim();

  // Cover statement. The coverage figure is only stated when all four layers ran.
  const evaluationMethodsUsed =
    `Automated accessibility evaluation using ${tools}. ` +
    (layers.length === 4
      ? 'This report covers the approximately 50–55% of WCAG 2.2 Level A and AA success criteria that are testable by automated tools. '
      : 'Automated tools can test only part of the WCAG 2.2 success criteria. ') +
    'Manual testing is required for full conformance coverage.';

  // Blank settings stay visible as highlighted placeholders rather than vanishing.
  const field = (label, value, placeholder) => ({ label, value: value || placeholder, placeholder: !value });

  return {
    meta: {
      appName: APP_NAME,
      docTitle: `${productName} - Accessibility Conformance Report`,
      title: `${productName} — Accessibility Conformance Report`,
      subtitle: '(Based on VPAT® Version 2.5Rev)',
      productName,
      productVersion: session.productVersion || '',
      reportDate: formatDate(reportDay),
      engineLine: layerNames.join(' · '),
      axeVersion,
      engineVersions,
      scanDates,
    },
    // Cover fields, in the order of the ITI template.
    coverFields: [
      field('Name of Product/Version', session.productVersion ? `${productName} ${session.productVersion}` : productName),
      field('Report Date', reportDay.toLocaleDateString('en-US', { year: 'numeric', month: 'long' })),
      field('Product Description', description, '[ENTER A BRIEF DESCRIPTION OF THE PRODUCT]'),
      field('Contact Information', contact, '[ENTER CONTACT EMAIL OR NAME]'),
      field('Notes', (session.notes || '').trim() || 'None'),
      field('Evaluation Methods Used', evaluationMethodsUsed),
      field('Prepared by', [preparedBy, company].filter(Boolean).join(', '), '[ENTER CONSULTANT NAME, COMPANY NAME]'),
      field('Report Date', formatDate(reportDay)),
    ],
    standards: [
      ['Web Content Accessibility Guidelines 2.2', 'Level A (Yes)\nLevel AA (Yes)\nLevel AAA (No)'],
    ],
    terms: [
      ['Supports', 'The functionality of the product has at least one method that meets the criterion without known defects or meets with equivalent facilitation.'],
      ['Partially Supports', 'Some functionality of the product does not meet the criterion.'],
      ['Does Not Support', 'The majority of product functionality does not meet the criterion.'],
      ['Not Applicable', 'The criterion is not relevant to the product.'],
      ['Not Evaluated', 'The product has not been evaluated against the criterion. This can be used only in WCAG Level AAA.'],
    ],
    // The template reserves Not Evaluated for Level AAA. An automated-only draft cannot
    // rate the criteria no tool tests, so the report says so instead of guessing a level.
    termsNote: counts['Not Evaluated']
      ? `Note on this draft: ${counts['Not Evaluated']} Level A and AA criteria that automated tools cannot test are marked Not Evaluated here. ` +
        'They must be evaluated manually and given one of the other levels before this report is final.'
      : '',
    tables: tables.map((t) => ({
      ...t,
      rows: t.rows.map((r) => ({ ...r, criteria: `${r.sc} ${r.name} (Level ${r.level})`, link: criterionLink(r.name) })),
    })),
    scope: {
      pages: scannedPages.map((p) => ({ name: p.name, url: p.url || '' })),
      outOfScope: scopeNote,
      facts: [
        ['Testing environment', uniqueSorted(scannedPages.map((p) => p.environment)).join('; ') || 'Not recorded'],
        ['Testing period', scanDates],
        ['Standard', 'WCAG 2.2 Level A and AA · VPAT® 2.5Rev'],
        ['Testing type', 'Automated scan only'],
      ],
    },
    scopeNote,
    legalDisclaimer,
    trademarkNotice:
      '"Voluntary Product Accessibility Template" and "VPAT" are registered service marks of the Information ' +
      'Technology Industry Council (ITI).',
    evaluationMethods,
    summary: { ...summary, cards: summaryCards },
    pages,
    pageAppendix,
  };
}

module.exports = { buildDocModel, APP_NAME };
