// Colours shared by the .docx and .pdf renderers so both reports look the same.
// Values are bare hex (docx wants "6B21A8", pdfmake wants "#6B21A8"; see hash()).
const THEME = {
  purple: '6B21A8',
  navy: '1A1A3E', // table header rows
  rowAlt: 'F8F8F8',
  surface: 'F9FAFB',
  text: '111827',
  muted: '6B7280',
  border: 'D1D5DB',
  white: 'FFFFFF',
  placeholder: 'FFF2CC',
};

// Background tint of the Conformance Level cell. The level is always written out in the
// cell, so the tint is a visual aid and never the only way to tell levels apart.
const LEVEL_TINT = {
  'Supports': 'E8F5E9',
  'Partially Supports': 'FFF8E1',
  'Does Not Support': 'FFEBEE',
  'Not Applicable': 'F5F5F5',
  'Not Evaluated': 'F5F5F5',
};

const hash = (hex) => `#${hex}`;

module.exports = { THEME, LEVEL_TINT, hash };
