const { pageFindings, hasEngineScan, hasKeyboardScan, KEYBOARD_CRITERIA, ENGINE_ORDER } = require('./findings');

const BUCKETS = {
  SUPPORTS: 'Supports',
  PARTIALLY: 'Partially Supports',
  DOES_NOT: 'Does Not Support',
  NOT_APPLICABLE: 'Not Applicable',
  NOT_EVALUATED: 'Not Evaluated',
};

// Criteria that need human judgment even though a scan collects evidence for them.
// They are always Not Evaluated; remarks.js adds the note pointing at the evidence.
const MANUAL_ONLY = new Set(['2.4.3']);

function getScannedPages(session) {
  return (session.pages || []).filter((p) => hasEngineScan(p) || hasKeyboardScan(p));
}

// Which scanning layers have a check for this criterion on this page. A rule engine
// counts only if the engine build that ran reported coverage for the criterion.
function coveringEngines(page, sc) {
  const engines = [];
  if (hasEngineScan(page)) {
    for (const engine of Object.keys(page.engines.coveredSc || {})) {
      if (page.engines.coveredSc[engine].includes(sc)) engines.push(engine);
    }
  }
  if (hasKeyboardScan(page) && KEYBOARD_CRITERIA.includes(sc) && !(sc === '2.4.11' && page.keyboardResults.viewportHidden)) {
    engines.push('Keyboard simulation');
  }
  return engines;
}

// Criteria that fail as a whole rather than instance by instance: any violation means
// the mechanism is absent. 2.4.1: no skip link is a total failure of the bypass mechanism.
const BINARY_FAILURES = ['2.4.1'];
// Instances of one criterion, summed across all scanned pages, from which the failure
// counts as affecting the majority of functionality.
const DOES_NOT_SUPPORT_THRESHOLD = 5;

// Conformance level for a criterion across all scanned pages. The ITI definitions are
// "some functionality" (Partially Supports) versus "the majority of functionality"
// (Does Not Support); the violation instance count is the proxy for that.
function getConformanceLevel(violationInstances, criterionId) {
  if (violationInstances === 0) return BUCKETS.SUPPORTS;
  if (BINARY_FAILURES.includes(criterionId)) return BUCKETS.DOES_NOT;
  if (violationInstances >= DOES_NOT_SUPPORT_THRESHOLD) return BUCKETS.DOES_NOT;
  return BUCKETS.PARTIALLY;
}

function emptyResult(bucket, extra) {
  return {
    bucket,
    totalPages: 0,
    withViolation: 0,
    instanceCount: 0,
    affectedPages: [],
    pageCounts: [],
    records: [],
    incompleteCount: 0,
    sources: [],
    ...extra,
  };
}

// Per VPAT 2.5 official definitions, with the violation instance count standing in for
// "some" versus "the majority of" functionality (see getConformanceLevel):
//  Supports           - no violations detected across all scanned pages
//  Partially Supports - 1 to 4 violation instances in total
//  Does Not Support   - 5 or more instances, any instance of a BINARY_FAILURES criterion,
//                       or a consultant override entered with a note
//  Not Applicable     - never assigned automatically; only when the consultant explicitly
//                       marks the criterion as not applying to this content type
//  Not Evaluated      - outside automated detection scope (no scanning layer has a check
//                       for this SC on any scanned page)
// "Scanned pages" for a criterion means the pages where a layer that covers it has run, so
// a page that only had an engine scan doesn't dilute a keyboard-only criterion.
// An instance is one deduplicated finding: one element failing the criterion on one page,
// however many engines (axe-core, IBM Equal Access, HTML CodeSniffer, keyboard) reported
// it. Every criterion goes through getConformanceLevel() with the total across pages.
function evaluateCriterion(sc, session) {
  if ((session.notApplicable || []).includes(sc)) {
    return emptyResult(BUCKETS.NOT_APPLICABLE);
  }
  const auto = evaluateAutomatically(sc, session);
  // A consultant can rate a criterion Does Not Support on their own judgment (for
  // example a failure the scans can't see). The automated result is kept alongside it.
  const note = (session.doesNotSupport || {})[sc];
  if (note) return { ...auto, bucket: BUCKETS.DOES_NOT, autoBucket: auto.bucket, overrideNote: note };
  return auto;
}

function evaluateAutomatically(sc, session) {

  const keyboardPages = (session.pages || []).filter(hasKeyboardScan).length;
  if (MANUAL_ONLY.has(sc)) {
    return emptyResult(BUCKETS.NOT_EVALUATED, { keyboardPages });
  }

  const pages = (session.pages || []).filter((p) => coveringEngines(p, sc).length > 0);
  if (pages.length === 0) {
    return emptyResult(BUCKETS.NOT_EVALUATED, { keyboardPages });
  }

  let withViolation = 0;
  let incompleteCount = 0;
  const affectedPages = [];
  const pageCounts = [];
  const records = [];
  const sources = new Set();

  for (const page of pages) {
    for (const engine of coveringEngines(page, sc)) sources.add(engine);
    if (hasEngineScan(page)) incompleteCount += (page.engines.review || {})[sc] || 0;

    const found = pageFindings(page).filter((r) => r.wcagCriterion === sc);
    if (found.length > 0) {
      withViolation += 1;
      affectedPages.push(page.name);
      pageCounts.push({ name: page.name, count: found.length });
      for (const r of found) records.push({ ...r, pageName: page.name });
    }
  }

  return {
    bucket: getConformanceLevel(records.length, sc),
    totalPages: pages.length,
    withViolation,
    instanceCount: records.length,
    affectedPages,
    pageCounts,
    records,
    incompleteCount,
    sources: [...sources].sort((a, b) => ENGINE_ORDER.indexOf(a) - ENGINE_ORDER.indexOf(b)),
    keyboardPages,
  };
}

function computeAllConformance(session, wcagList) {
  return wcagList.map((criterion) => ({
    ...criterion,
    ...evaluateCriterion(criterion.sc, session),
  }));
}

function summarizeBuckets(results) {
  const counts = {
    [BUCKETS.SUPPORTS]: 0,
    [BUCKETS.PARTIALLY]: 0,
    [BUCKETS.DOES_NOT]: 0,
    [BUCKETS.NOT_APPLICABLE]: 0,
    [BUCKETS.NOT_EVALUATED]: 0,
  };
  for (const r of results) {
    counts[r.bucket] = (counts[r.bucket] || 0) + 1;
  }
  return counts;
}

module.exports = {
  BUCKETS,
  MANUAL_ONLY,
  BINARY_FAILURES,
  DOES_NOT_SUPPORT_THRESHOLD,
  getConformanceLevel,
  getScannedPages,
  coveringEngines,
  evaluateCriterion,
  computeAllConformance,
  summarizeBuckets,
};
